import sys
sys.path.insert(0,'/tmp')
from lib2 import *
combos=["C-a","C-e","C-w","C-u","C-k","C-h","C-j","C-m","C-t","C-f","C-b","C-n","C-p","M-b","M-f","M-d","M-BSpace","C-Left","C-Right","C-Delete","C-BSpace","Home","End","Delete","Left","Right","Up","Down","PageUp","PageDown","Escape","C-Home","C-End","S-Left","S-Right"]
