            ls=lines()
            alive = any("Search" in l for l in ls)
            if not alive:
                print(f"{combo}: EXITED/no UI")
            else:
                print(f"{combo}: search={ls[1][1:29]!r} cur={cursor()} help={'Global' in ''.join(ls)} status={ls[-1]!r}")
        except Exception as e:
            print(combo, "capture err", e)
    except Exception as e:
        print(combo, "err", e)
