use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use serde_json::{Map, Value};
use std::collections::HashMap;
use std::path::{Path, PathBuf};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Action {
    Quit,
    Suspend,
    Resume,
    Refresh,
    LoopOverTabs,
    BackLoopOverTabs,
    ProcessReplace,
    ShowHelp,
    Help,
    Tick,
    Render,
}

impl Action {
    pub fn from_name(name: &str) -> Result<Action, String> {
        match name {
            "Quit" => Ok(Action::Quit),
            "Suspend" => Ok(Action::Suspend),
            "Resume" => Ok(Action::Resume),
            "Refresh" => Ok(Action::Refresh),
            "LoopOverTabs" => Ok(Action::LoopOverTabs),
            "BackLoopOverTabs" => Ok(Action::BackLoopOverTabs),
            "ProcessReplace" => Ok(Action::ProcessReplace),
            "ShowHelp" => Ok(Action::ShowHelp),
            "Help" => Ok(Action::Help),
            "Tick" => Ok(Action::Tick),
            "Render" => Ok(Action::Render),
            _ => Err(format!("Unknown Action variant: {}", name)),
        }
    }
}

#[derive(Clone, Debug)]
pub struct Config {
    pub keybindings: HashMap<KeyEvent, Action>,
}

pub fn config_dir() -> PathBuf {
    dirs::config_dir()
        .unwrap_or_else(|| PathBuf::from(".config"))
        .join("serpl")
}

fn default_keybindings() -> HashMap<(KeyCode, KeyModifiers), Action> {
    let mut map = HashMap::new();
    let mut add = |code: KeyCode, modifiers: KeyModifiers, action: Action| {
        map.insert((code, modifiers), action);
    };
    add(KeyCode::Char('d'), KeyModifiers::CONTROL, Action::Quit);
    add(KeyCode::Char('c'), KeyModifiers::CONTROL, Action::Quit);
    add(KeyCode::Char('z'), KeyModifiers::CONTROL, Action::Suspend);
    add(KeyCode::Char('r'), KeyModifiers::CONTROL, Action::Refresh);
    add(KeyCode::Tab, KeyModifiers::NONE, Action::LoopOverTabs);
    add(KeyCode::BackTab, KeyModifiers::SHIFT, Action::BackLoopOverTabs);
    add(KeyCode::Char('o'), KeyModifiers::CONTROL, Action::ProcessReplace);
    add(KeyCode::Char('b'), KeyModifiers::CONTROL, Action::ShowHelp);
    map
}

pub fn key_event_key(code: KeyCode, modifiers: KeyModifiers) -> (KeyCode, KeyModifiers) {
    // Normalise the parts of a key event that are used when matching it
    // against the configured keybindings.
    let mut mods = modifiers;
    mods.remove(KeyModifiers::NONE);
    // Crossterm reports BackTab together with SHIFT.
    if code == KeyCode::BackTab {
        mods.insert(KeyModifiers::SHIFT);
    }
    (code, mods)
}

impl Config {
    pub fn action_for(&self, event: KeyEvent) -> Option<Action> {
        self.keybindings.get(&event).copied()
    }

    pub fn load(dir: &Path) -> Result<Config, String> {
        let mut bindings = default_keybindings();
        let file = find_config_file(dir);
        if let Some(path) = file {
            let values = read_config_values(&path)?;
            // Find the `keybindings` entry.  Configuration keys are
            // case-insensitive, mirroring the behaviour of the format
            // used by the original program.
            let mut found: Option<&Value> = None;
            for (key, value) in values.iter() {
                if key.to_lowercase() == "keybindings" {
                    found = Some(value);
                }
            }
            if let Some(value) = found {
                let map = match value {
                    Value::Object(map) => map,
                    other => {
                        return Err(format!(
                            "invalid type: {}, expected a map",
                            describe_type(other)
                        ))
                    }
                };
                // Actions are validated for every entry before any key
                // is parsed, because the original program deserialises
                // the action map before it converts the key strings.
                let mut parsed_actions: Vec<(String, Action)> = Vec::new();
                for (raw_key, raw_value) in map.iter() {
                    let action_name = match raw_value {
                        Value::String(text) => text.clone(),
                        Value::Number(number) => number.to_string(),
                        Value::Bool(flag) => flag.to_string(),
                        Value::Null => {
                            return Err(format!(
                                "invalid type: unit value, expected a string for key `keybindings.{}` in {}",
                                raw_key.to_lowercase(),
                                relative_path(&path)
                            ))
                        }
                        Value::Array(_) => {
                            return Err(format!(
                                "invalid type: sequence, expected a string for key `keybindings.{}` in {}",
                                raw_key.to_lowercase(),
                                relative_path(&path)
                            ))
                        }
                        Value::Object(_) => {
                            return Err(
                                "invalid type: map, expected a string".to_string()
                            )
                        }
                    };
                    let action = Action::from_name(&action_name)?;
                    parsed_actions.push((raw_key.clone(), action));
                }
                for (raw_key, action) in parsed_actions {
                    let event = parse_key_binding(&raw_key);
                    bindings.insert(key_event_key(event.code, event.modifiers), action);
                }
            }
        }

        let keybindings = bindings
            .into_iter()
            .map(|((code, modifiers), action)| {
                (KeyEvent::new(code, modifiers), action)
            })
            .collect();
        Ok(Config { keybindings })
    }
}

fn describe_type(value: &Value) -> String {
    match value {
        Value::Null => "unit value".to_string(),
        Value::Bool(flag) => format!("boolean `{}`", flag),
        Value::Number(number) => {
            if number.is_i64() || number.is_u64() {
                format!("64-bit integer `{}`", number)
            } else {
                format!("64-bit floating point `{}`", number)
            }
        }
        Value::String(text) => format!("string \"{}\"", text),
        Value::Array(_) => "sequence".to_string(),
        Value::Object(_) => "map".to_string(),
    }
}

fn find_config_file(dir: &Path) -> Option<PathBuf> {
    for ext in ["json5", "json", "yaml", "toml", "ini"] {
        let candidate = dir.join(format!("config.{}", ext));
        if candidate.is_file() {
            return Some(candidate);
        }
    }
    None
}

pub fn relative_path(path: &Path) -> String {
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    make_relative(&cwd, path)
}

fn make_relative(from: &Path, to: &Path) -> String {
    let from_components: Vec<String> = from
        .components()
        .map(|component| component.as_os_str().to_string_lossy().into_owned())
        .collect();
    let to_components: Vec<String> = to
        .components()
        .map(|component| component.as_os_str().to_string_lossy().into_owned())
        .collect();
    // Only produce a relative path when both paths share the same
    // (absolute or relative) root.
    if from_components.first() != to_components.first() {
        return to.display().to_string();
    }
    let mut common = 0;
    while common < from_components.len()
        && common < to_components.len()
        && from_components[common] == to_components[common]
    {
        common += 1;
    }
    if common == 0 {
        return to.display().to_string();
    }
    let mut result: Vec<String> = Vec::new();
    for _ in common..from_components.len() {
        result.push("..".to_string());
    }
    result.extend(to_components[common..].iter().cloned());
    if result.is_empty() {
        ".".to_string()
    } else {
        result.join("/")
    }
}

fn read_config_values(path: &Path) -> Result<Map<String, Value>, String> {
    let text = std::fs::read_to_string(path)
        .map_err(|err| err.to_string())?;
    let extension = path
        .extension()
        .map(|ext| ext.to_string_lossy().to_lowercase())
        .unwrap_or_default();
    let value = match extension.as_str() {
        "json" => serde_json::from_str::<Value>(&text)
            .map_err(|err| format_json_error(err, path)),
        "yaml" => parse_simple_yaml(&text),
        "toml" => parse_simple_toml(&text),
        "ini" => parse_simple_ini(&text),
        _ => parse_json5(&text, path),
    }?;
    match value {
        Value::Object(map) => Ok(map),
        other => Err(format!(
            "invalid type: {}, expected a map in {} in {}",
            describe_type(&other),
            relative_path(path),
            relative_path(path)
        )),
    }
}

fn format_json_error(err: serde_json::Error, path: &Path) -> String {
    let mut message = err.to_string();
    // serde_json reports e.g. "key must be a string at line 1 column 2".
    // The original program appends the configuration file name.
    if !message.contains(" in ") {
        message = format!("{} in {}", message, relative_path(path));
    }
    message
}

// ---------------------------------------------------------------------
// Key parsing
// ---------------------------------------------------------------------

fn parse_key_binding(raw: &str) -> KeyEvent {
    parse_key(raw).unwrap()
}

pub fn parse_key(raw: &str) -> Result<KeyEvent, String> {
    let lowered = raw.to_lowercase();
    let stripped = lowered
        .trim_start_matches('<')
        .trim_end_matches('>')
        .to_string();
    parse_key_inner(&stripped, KeyModifiers::NONE)
}

fn parse_key_inner(text: &str, modifiers: KeyModifiers) -> Result<KeyEvent, String> {
    if let Some(rest) = text.strip_prefix("ctrl-") {
        return parse_key_inner(rest, modifiers | KeyModifiers::CONTROL);
    }
    if let Some(rest) = text.strip_prefix("alt-") {
        return parse_key_inner(rest, modifiers | KeyModifiers::ALT);
    }
    if let Some(rest) = text.strip_prefix("shift-") {
        return parse_key_inner(rest, modifiers | KeyModifiers::SHIFT);
    }
    let code = match text {
        "esc" => KeyCode::Esc,
        "enter" => KeyCode::Enter,
        "left" => KeyCode::Left,
        "right" => KeyCode::Right,
        "up" => KeyCode::Up,
        "down" => KeyCode::Down,
        "home" => KeyCode::Home,
        "end" => KeyCode::End,
        "pageup" => KeyCode::PageUp,
        "pagedown" => KeyCode::PageDown,
        "backspace" => KeyCode::Backspace,
        "delete" => KeyCode::Delete,
        "insert" => KeyCode::Insert,
        "tab" => KeyCode::Tab,
        "backtab" => KeyCode::BackTab,
        "space" => KeyCode::Char(' '),
        _ => {
            if let Some(number) = text
                .strip_prefix('f')
                .and_then(|num| num.parse::<u8>().ok())
                .filter(|num| (1..=12).contains(num))
            {
                KeyCode::F(number)
            } else if text.chars().count() == 1 {
                let ch = text.chars().next().unwrap();
                if modifiers.contains(KeyModifiers::SHIFT) {
                    let upper: String = ch.to_uppercase().collect();
                    if upper.chars().count() == 1 {
                        return Ok(KeyEvent::new(
                            KeyCode::Char(upper.chars().next().unwrap()),
                            modifiers,
                        ));
                    }
                }
                KeyCode::Char(ch)
            } else {
                return Err(format!("Unable to parse {}", text));
            }
        }
    };
    Ok(KeyEvent::new(code, modifiers))
}

// ---------------------------------------------------------------------
// Minimal parsers for the configuration formats.
// ---------------------------------------------------------------------

pub fn parse_json5(text: &str, path: &Path) -> Result<Value, String> {
    let mut parser = Json5Parser {
        chars: text.chars().collect(),
        pos: 0,
        path: path.to_path_buf(),
        source: text.to_string(),
    };
    parser.skip_trivia();
    let value = parser.parse_value()?;
    parser.skip_trivia();
    if parser.pos != parser.chars.len() {
        return Err(parser.error_here("expected end of input"));
    }
    Ok(value)
}

struct Json5Parser {
    chars: Vec<char>,
    pos: usize,
    path: PathBuf,
    source: String,
}

impl Json5Parser {
    fn error_here(&self, message: &str) -> String {
        // Render a pest-like error snippet.
        let mut line_no = 1usize;
        let mut line_start = 0usize;
        let byte_pos = self
            .source
            .char_indices()
            .map(|(index, _)| index)
            .nth(self.pos)
            .unwrap_or(self.source.len());
        for (index, ch) in self.source.char_indices() {
            if index >= byte_pos {
                break;
            }
            if ch == '\n' {
                line_no += 1;
                line_start = index + 1;
            }
        }
        let line_end = self.source[line_start..]
            .find('\n')
            .map(|offset| line_start + offset)
            .unwrap_or(self.source.len());
        let line_text = &self.source[line_start..line_end];
        let column = self.source[line_start..byte_pos].chars().count() + 1;
        let marker = format!("{}^---", " ".repeat(column - 1));
        format!(
            " --> {}:{}\n        |\n      {} | {}\n        | {}\n        |\n        = {} in {}",
            line_no,
            column,
            line_no,
            line_text,
            marker,
            message,
            relative_path(&self.path)
        )
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next_char(&mut self) -> Option<char> {
        let ch = self.peek();
        if ch.is_some() {
            self.pos += 1;
        }
        ch
    }

    fn skip_trivia(&mut self) {
        loop {
            match self.peek() {
                Some(ch) if ch.is_whitespace() => {
                    self.pos += 1;
                }
                Some('/') => {
                    if self.chars.get(self.pos + 1) == Some(&'/') {
                        while let Some(ch) = self.peek() {
                            if ch == '\n' {
                                break;
                            }
                            self.pos += 1;
                        }
                    } else if self.chars.get(self.pos + 1) == Some(&'*') {
                        self.pos += 2;
                        while self.pos < self.chars.len() {
                            if self.chars[self.pos] == '*'
                                && self.chars.get(self.pos + 1) == Some(&'/')
                            {
                                self.pos += 2;
                                break;
                            }
                            self.pos += 1;
                        }
                    } else {
                        break;
                    }
                }
                _ => break,
            }
        }
    }

    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_trivia();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') | Some('\'') => Ok(Value::String(self.parse_string()?)),
            Some(_) => self.parse_literal(),
            None => Err(self.error_here(
                "expected array, boolean, null, number, object, or string",
            )),
        }
    }

    fn parse_object(&mut self) -> Result<Value, String> {
        self.next_char(); // {
        let mut map = Map::new();
        loop {
            self.skip_trivia();
            match self.peek() {
                Some('}') => {
                    self.next_char();
                    break;
                }
                Some(_) => {
                    let key = if self.peek() == Some('"') || self.peek() == Some('\'') {
                        self.parse_string()?
                    } else {
                        // Identifier key.
                        let start = self.pos;
                        while let Some(ch) = self.peek() {
                            if ch.is_alphanumeric() || ch == '_' || ch == '$' || ch == '-' {
                                self.pos += 1;
                            } else {
                                break;
                            }
                        }
                        if start == self.pos {
                            return Err(self
                                .error_here("expected identifier or string"));
                        }
                        self.chars[start..self.pos].iter().collect()
                    };
                    self.skip_trivia();
                    if self.next_char() != Some(':') {
                        return Err(self.error_here("expected `:`"));
                    }
                    let value = self.parse_value()?;
                    map.insert(key, value);
                    self.skip_trivia();
                    match self.peek() {
                        Some(',') => {
                            self.next_char();
                        }
                        Some('}') => {}
                        _ => return Err(self.error_here("expected `,` or `}`")),
                    }
                }
                None => {
                    return Err(self.error_here(
                        "expected array, boolean, null, number, object, or string",
                    ))
                }
            }
        }
        Ok(Value::Object(map))
    }

    fn parse_array(&mut self) -> Result<Value, String> {
        self.next_char(); // [
        let mut values = Vec::new();
        loop {
            self.skip_trivia();
            if self.peek() == Some(']') {
                self.next_char();
                break;
            }
            let value = self.parse_value()?;
            values.push(value);
            self.skip_trivia();
            match self.peek() {
                Some(',') => {
                    self.next_char();
                }
                Some(']') => {}
                _ => return Err(self.error_here("expected `,` or `]`")),
            }
        }
        Ok(Value::Array(values))
    }

    fn parse_string(&mut self) -> Result<String, String> {
        let quote = self.next_char().unwrap();
        let mut output = String::new();
        while let Some(ch) = self.next_char() {
            if ch == quote {
                return Ok(output);
            }
            if ch == '\\' {
                let escaped = self.next_char().ok_or_else(|| {
                    self.error_here("unterminated string")
                })?;
                match escaped {
                    'n' => output.push('\n'),
                    'r' => output.push('\r'),
                    't' => output.push('\t'),
                    'b' => output.push('\u{0008}'),
                    'f' => output.push('\u{000C}'),
                    'u' => {
                        let mut code = 0u32;
                        for _ in 0..4 {
                            let digit = self.next_char().ok_or_else(|| {
                                self.error_here("invalid unicode escape")
                            })?;
                            code = code * 16
                                + digit.to_digit(16).ok_or_else(|| {
                                    self.error_here("invalid unicode escape")
                                })?;
                        }
                        if let Some(ch) = char::from_u32(code) {
                            output.push(ch);
                        }
                    }
                    '\n' => {}
                    other => output.push(other),
                }
            } else {
                output.push(ch);
            }
        }
        Err(self.error_here("unterminated string"))
    }

    fn parse_literal(&mut self) -> Result<Value, String> {
        let start = self.pos;
        while let Some(ch) = self.peek() {
            if ch == ','
                || ch == '}'
                || ch == ']'
                || ch == ':'
                || ch.is_whitespace()
            {
                break;
            }
            self.pos += 1;
        }
        let token: String = self.chars[start..self.pos].iter().collect();
        match token.as_str() {
            "true" => Ok(Value::Bool(true)),
            "false" => Ok(Value::Bool(false)),
            "null" | "Null" | "NULL" => Ok(Value::Null),
            "Infinity" | "+Infinity" => {
                Ok(Value::Number(serde_json::Number::from_f64(f64::INFINITY).unwrap_or_else(|| serde_json::Number::from(0))))
            }
            "-Infinity" => {
                Ok(Value::Number(serde_json::Number::from_f64(f64::NEG_INFINITY).unwrap_or_else(|| serde_json::Number::from(0))))
            }
            "NaN" | "+NaN" | "-NaN" => Ok(Value::Null),
            _ => {
                if let Ok(int) = token.parse::<i64>() {
                    Ok(Value::Number(int.into()))
                } else if let Ok(uint) = token.parse::<u64>() {
                    Ok(Value::Number(uint.into()))
                } else if let Some(hex) =
                    token.strip_prefix("0x").or_else(|| token.strip_prefix("0X"))
                {
                    i64::from_str_radix(hex, 16)
                        .map(|value| Value::Number(value.into()))
                        .map_err(|_| {
                            self.error_here(
                                "expected array, boolean, null, number, object, or string",
                            )
                        })
                } else if let Ok(float) = token.parse::<f64>() {
                    serde_json::Number::from_f64(float)
                        .map(Value::Number)
                        .ok_or_else(|| {
                            self.error_here(
                                "expected array, boolean, null, number, object, or string",
                            )
                        })
                } else {
                    Err(self.error_here(
                        "expected array, boolean, null, number, object, or string",
                    ))
                }
            }
        }
    }
}

// Very small YAML subset: nested maps with scalar values.
fn parse_simple_yaml(text: &str) -> Result<Value, String> {
    let mut root = Map::new();
    // Stack of (indent, map pointer path).
    let mut paths: Vec<(usize, Vec<String>)> = vec![(0, Vec::new())];
    for raw_line in text.lines() {
        if raw_line.trim().is_empty() || raw_line.trim_start().starts_with('#') {
            continue;
        }
        let indent = raw_line.len() - raw_line.trim_start().len();
        let line = raw_line.trim();
        let Some((key, rest)) = line.split_once(':') else {
            return Err(format!("could not parse YAML line: {}", line));
        };
        let key = unquote(key.trim());
        let rest = rest.trim();
        while let Some((level, _)) = paths.last() {
            if indent <= *level && paths.len() > 1 {
                paths.pop();
            } else {
                break;
            }
        }
        let mut key_path = paths.last().map(|(_, path)| path.clone()).unwrap_or_default();
        if rest.is_empty() {
            key_path.push(key);
            insert_yaml_value(&mut root, &key_path, Value::Object(Map::new()));
            paths.push((indent, key_path));
        } else {
            key_path.push(key);
            insert_yaml_value(&mut root, &key_path, yaml_scalar(rest));
        }
    }
    Ok(Value::Object(root))
}

fn insert_yaml_value(map: &mut Map<String, Value>, path: &[String], value: Value) {
    if path.len() == 1 {
        map.insert(path[0].clone(), value);
        return;
    }
    let entry = map
        .entry(path[0].clone())
        .or_insert_with(|| Value::Object(Map::new()));
    if let Value::Object(child) = entry {
        insert_yaml_value(child, &path[1..], value);
    }
}

fn yaml_scalar(text: &str) -> Value {
    match text {
        "true" => Value::Bool(true),
        "false" => Value::Bool(false),
        "null" | "~" => Value::Null,
        _ => {
            if let Ok(int) = text.parse::<i64>() {
                Value::Number(int.into())
            } else {
                Value::String(unquote(text))
            }
        }
    }
}

fn unquote(text: &str) -> String {
    let trimmed = text.trim();
    if trimmed.len() >= 2
        && ((trimmed.starts_with('"') && trimmed.ends_with('"'))
            || (trimmed.starts_with('\'') && trimmed.ends_with('\'')))
    {
        trimmed[1..trimmed.len() - 1].to_string()
    } else {
        trimmed.to_string()
    }
}

// Very small TOML subset: [section] tables and `key = value` pairs and
// inline tables as values.
fn parse_simple_toml(text: &str) -> Result<Value, String> {
    let mut root = Map::new();
    let mut current_section: Vec<String> = Vec::new();
    for raw_line in text.lines() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if line.starts_with('[') && line.ends_with(']') {
            current_section = line[1..line.len() - 1]
                .split('.')
                .map(|part| unquote(part.trim()))
                .collect();
            ensure_map_path(&mut root, &current_section);
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            return Err("TOML parse error".to_string());
        };
        let mut path = current_section.clone();
        path.push(unquote(key.trim()));
        insert_yaml_value(&mut root, &path, toml_value(value.trim())?);
    }
    Ok(Value::Object(root))
}

fn ensure_map_path(map: &mut Map<String, Value>, path: &[String]) {
    if path.is_empty() {
        return;
    }
    let entry = map
        .entry(path[0].clone())
        .or_insert_with(|| Value::Object(Map::new()));
    if let Value::Object(child) = entry {
        ensure_map_path(child, &path[1..]);
    }
}

fn toml_value(text: &str) -> Result<Value, String> {
    if text.starts_with('{') && text.ends_with('}') {
        let mut map = Map::new();
        let inner = &text[1..text.len() - 1];
        for part in split_top_level(inner, ',') {
            if part.trim().is_empty() {
                continue;
            }
            let (key, value) = part
                .split_once('=')
                .ok_or_else(|| "TOML parse error".to_string())?;
            map.insert(unquote(key.trim()), toml_value(value.trim())?);
        }
        Ok(Value::Object(map))
    } else if text.starts_with('[') && text.ends_with(']') {
        let mut values = Vec::new();
        for part in split_top_level(&text[1..text.len() - 1], ',') {
            if !part.trim().is_empty() {
                values.push(toml_value(part.trim())?);
            }
        }
        Ok(Value::Array(values))
    } else {
        Ok(yaml_scalar(text))
    }
}

fn split_top_level(text: &str, delimiter: char) -> Vec<String> {
    let mut parts = Vec::new();
    let mut depth = 0i32;
    let mut quote: Option<char> = None;
    let mut current = String::new();
    for ch in text.chars() {
        match quote {
            Some(q) => {
                current.push(ch);
                if ch == q {
                    quote = None;
                }
            }
            None => {
                if ch == '"' || ch == '\'' {
                    quote = Some(ch);
                    current.push(ch);
                } else if ch == '{' || ch == '[' {
                    depth += 1;
                    current.push(ch);
                } else if ch == '}' || ch == ']' {
                    depth -= 1;
                    current.push(ch);
                } else if ch == delimiter && depth == 0 {
                    parts.push(current);
                    current = String::new();
                } else {
                    current.push(ch);
                }
            }
        }
    }
    parts.push(current);
    parts
}

fn parse_simple_ini(text: &str) -> Result<Value, String> {
    let mut root = Map::new();
    let mut section: Vec<String> = Vec::new();
    for raw_line in text.lines() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with(';') || line.starts_with('#') {
            continue;
        }
        if line.starts_with('[') && line.ends_with(']') {
            section = vec![line[1..line.len() - 1].trim().to_string()];
            ensure_map_path(&mut root, &section);
            continue;
        }
        if let Some((key, value)) = line.split_once('=') {
            let mut path = section.clone();
            path.push(key.trim().to_string());
            insert_yaml_value(&mut root, &path, Value::String(value.trim().to_string()));
        }
    }
    Ok(Value::Object(root))
}
EOF
"}

