use unicode_width::UnicodeWidthChar;

#[derive(Clone, Debug, Default)]
pub struct Input {
    pub value: String,
    // Cursor as a byte index into `value`, always on a char boundary.
    pub cursor: usize,
}

impl Input {
    pub fn new() -> Input {
        Input {
            value: String::new(),
            cursor: 0,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.value.is_empty()
    }

    pub fn visual_cursor(&self) -> usize {
        self.value[..self.cursor]
            .chars()
            .map(|ch| UnicodeWidthChar::width(ch).unwrap_or(0))
            .sum()
    }

    pub fn visual_scroll(&self, width: usize) -> usize {
        if width == 0 {
            return 0;
        }
        // One column is kept so the cursor cell itself stays visible.
        self.visual_cursor().saturating_sub(width - 1)
    }

    pub fn insert_char(&mut self, ch: char) -> bool {
        if ch == '\n' || ch == '\r' {
            return false;
        }
        self.value.insert(self.cursor, ch);
        self.cursor += ch.len_utf8();
        true
    }

    fn previous_char_boundary(&self, from: usize) -> usize {
        if from == 0 {
            return 0;
        }
        let mut index = from - 1;
        while !self.value.is_char_boundary(index) {
            index -= 1;
        }
        index
    }

    fn next_char_boundary(&self, from: usize) -> usize {
        if from >= self.value.len() {
            return self.value.len();
        }
        let mut index = from + 1;
        while !self.value.is_char_boundary(index) {
            index += 1;
        }
        index
    }

    pub fn delete_previous_char(&mut self) -> bool {
        if self.cursor == 0 {
            return false;
        }
        let start = self.previous_char_boundary(self.cursor);
        self.value.replace_range(start..self.cursor, "");
        self.cursor = start;
        true
    }

    pub fn delete_next_char(&mut self) -> bool {
        if self.cursor >= self.value.len() {
            return false;
        }
        let end = self.next_char_boundary(self.cursor);
        self.value.replace_range(self.cursor..end, "");
        true
    }

    pub fn move_left(&mut self) {
        self.cursor = self.previous_char_boundary(self.cursor);
    }

    pub fn move_right(&mut self) {
        self.cursor = self.next_char_boundary(self.cursor);
    }

    pub fn move_start(&mut self) {
        self.cursor = 0;
    }

    pub fn move_end(&mut self) {
        self.cursor = self.value.len();
    }

    fn word_starts(&self) -> Vec<usize> {
        let mut starts = Vec::new();
        let mut in_word = false;
        for (index, ch) in self.value.char_indices() {
            let is_word = ch.is_alphanumeric();
            if is_word && !in_word {
                starts.push(index);
            }
            in_word = is_word;
        }
        starts
    }

    pub fn previous_word_start(&self) -> usize {
        // Largest word start before the cursor, or zero.  A cursor inside
        // a word returns the start of that word; a cursor at the start of
        // a word returns the previous word's start.
        let mut result = 0;
        for start in self.word_starts() {
            if start < self.cursor {
                result = start;
            } else {
                break;
            }
        }
        result
    }

    pub fn next_word_start(&self) -> usize {
        for start in self.word_starts() {
            if start > self.cursor {
                return start;
            }
        }
        self.value.len()
    }

    pub fn move_previous_word(&mut self) {
        self.cursor = self.previous_word_start();
    }

    pub fn move_next_word(&mut self) {
        self.cursor = self.next_word_start();
    }

    pub fn delete_to_previous_word(&mut self) -> bool {
        if self.cursor == 0 {
            return false;
        }
        // Determine the range to remove.  If the cursor is inside a word
        // or just after a word, the word itself is removed.  Otherwise
        // (the cursor is after a word followed by separators, or at the
        // start of a word) the preceding word plus any separators up to
        // the cursor are removed.
        let starts = self.word_starts();
        let mut target: Option<usize> = None;
        for (index, start) in starts.iter().enumerate() {
            let end = starts
                .get(index + 1)
                .copied()
                .unwrap_or(self.value.len());
            // End of the alphanumeric run itself, not the next start.
            let run_end = self.value[*start..end]
                .char_indices()
                .take_while(|(_, ch)| ch.is_alphanumeric())
                .map(|(offset, ch)| start + offset + ch.len_utf8())
                .last()
                .unwrap_or(*start);
            if *start < self.cursor && self.cursor <= run_end {
                target = Some(*start);
                break;
            }
        }
        let target = target.unwrap_or_else(|| self.previous_word_start());
        if target == self.cursor {
            return false;
        }
        self.value.replace_range(target..self.cursor, "");
        self.cursor = target;
        true
    }

    pub fn delete_to_next_word(&mut self) -> bool {
        if self.cursor >= self.value.len() {
            return false;
        }
        let target = self.next_word_start();
        self.value.replace_range(self.cursor..target, "");
        true
    }

    pub fn delete_all(&mut self) -> bool {
        if self.value.is_empty() {
            self.cursor = 0;
            return false;
        }
        self.value.clear();
        self.cursor = 0;
        true
    }

    pub fn delete_to_end(&mut self) -> bool {
        if self.cursor >= self.value.len() {
            return false;
        }
        self.value.truncate(self.cursor);
        true
    }
}
