        if self.cursor == 0 {
            return false;
        }
        let start = self.previous_char_boundary(self.cursor);
        self.value.replace_range(start..self.cursor, "");
        self.cursor = start;
        true
    }

    pub fn delete_next_char(&mut self) -> bool {
        if self.cursor >= self.value.len() {
            return false;
        }
        let end = self.next_char_boundary(self.cursor);
        self.value.replace_range(self.cursor..end, "");
        true
    }

    pub fn move_left(&mut self) {
        self.cursor = self.previous_char_boundary(self.cursor);
    }

    pub fn move_right(&mut self) {
        self.cursor = self.next_char_boundary(self.cursor);
    }

    pub fn move_start(&mut self) {
        self.cursor = 0;
    }

    pub fn move_end(&mut self) {
        self.cursor = self.value.len();
    }

    fn word_starts(&self) -> Vec<usize> {
        let mut starts = Vec::new();
        let mut in_word = false;
        for (index, ch) in self.value.char_indices() {
            let is_word = ch.is_alphanumeric();
            if is_word && !in_word {
                starts.push(index);
            }
            in_word = is_word;
        }
        starts
    }

    pub fn previous_word_start(&self) -> usize {
        // Largest word start before the cursor, or zero.  A cursor inside
        // a word returns the start of that word; a cursor at the start of
        // a word returns the previous word's start.
        let mut result = 0;
        for start in self.word_starts() {
            if start < self.cursor {
                result = start;
            } else {
                break;
            }
        }
        result
    }

    pub fn next_word_start(&self) -> usize {
        for start in self.word_starts() {
            if start > self.cursor {
                return start;
            }
        }
        self.value.len()
    }

