{"command":"cat > /workspace/src/search.rs <<'EOF'
use crate::replace::highlight_regex;
use regex::{Regex, RegexBuilder};
use std::collections::{HashMap, HashSet};
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::sync::atomic::{AtomicUsize, Ordering};

static NEXT_FILE_ID: AtomicUsize = AtomicUsize::new(1);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SearchMode {
    Simple,
    MatchCase,
    MatchWholeWord,
    MatchCaseWholeWord,
    Regex,
}

impl SearchMode {
    pub fn title(self) -> &'static str {
        match self {
            SearchMode::Simple => "Simple",
            SearchMode::MatchCase => "Match Case",
            SearchMode::MatchWholeWord => "Match Whole Word",
            SearchMode::MatchCaseWholeWord => "Match Case Whole Word",
            SearchMode::Regex => "Regex",
        }
    }

    pub fn next(self) -> SearchMode {
        match self {
            SearchMode::Simple => SearchMode::MatchCase,
            SearchMode::MatchCase => SearchMode::MatchWholeWord,
            SearchMode::MatchWholeWord => SearchMode::MatchCaseWholeWord,
            SearchMode::MatchCaseWholeWord => SearchMode::Regex,
            SearchMode::Regex => SearchMode::Simple,
        }
    }

    pub fn is_case_insensitive(self) -> bool {
        matches!(
            self,
            SearchMode::Simple
                | SearchMode::MatchWholeWord
        )
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ReplaceMode {
    Simple,
    PreserveCase,
    DeleteLine,
}

impl ReplaceMode {
    pub fn title(self) -> &'static str {
        match self {
            ReplaceMode::Simple => "Simple",
            ReplaceMode::PreserveCase => "Preserve Case",
            ReplaceMode::DeleteLine => "Delete Line",
        }
    }

    pub fn next(self) -> ReplaceMode {
        match self {
            ReplaceMode::Simple => ReplaceMode::PreserveCase,
            ReplaceMode::PreserveCase => ReplaceMode::DeleteLine,
            ReplaceMode::DeleteLine => ReplaceMode::Simple,
        }
    }
}

#[derive(Clone, Debug)]
pub struct MatchEntry {
    pub line_number: usize,
    pub text: String,
    pub valid_index: usize,
}

#[derive(Clone, Debug)]
pub struct PreviewRow {
    pub line_number: usize,
    pub text: String,
    pub is_center: bool,
    pub is_separator: bool,
    pub block_index: usize,
}

#[derive(Clone, Debug, Default)]
pub struct PreviewSource {
    pub combined_lines: Vec<String>,
    pub base_index: usize,
    pub own_count: usize,
    pub prev_external_match_idx: Option<usize>,
}

#[derive(Clone, Debug)]
pub struct FileResult {
    pub id: usize,
    pub actual_path: String,
    pub display_path: String,
    pub count: usize,
    pub matches: Vec<MatchEntry>,
    pub source: PreviewSource,
    pub preview_rows: Vec<PreviewRow>,
}

impl FileResult {
    pub fn rebuild_preview(&mut self) {
        let mut rows: Vec<PreviewRow> = Vec::new();
        let own_end = if self.source.own_count == 0 {
            self.source.base_index
        } else {
            self.source.base_index + self.source.own_count - 1
        };
        for (block_index, matched) in self.matches.iter().enumerate() {
            let combined_idx = self.source.base_index + matched.valid_index;
            if combined_idx >= self.source.combined_lines.len() {
                continue;
            }
            let prev_idx = if block_index > 0 {
                Some(
                    self.source.base_index
                        + self.matches[block_index - 1].valid_index,
                )
            } else {
                self.source.prev_external_match_idx
            };
            let next_idx = self
                .matches
                .get(block_index + 1)
                .map(|entry| self.source.base_index + entry.valid_index);
            let start_by_context = combined_idx.saturating_sub(3);
            let start = match prev_idx {
                Some(previous) => start_by_context.max(previous),
                None => start_by_context,
            };
            let end_by_context = combined_idx + 3;
            let end = match next_idx {
                Some(next) => end_by_context.min(next.saturating_sub(1)),
                None => end_by_context.min(own_end),
            };
            let end = end.min(self.source.combined_lines.len() - 1);
            if start > end {
                continue;
            }
            let matched_position = combined_idx - start;
            let start_number = matched.line_number.saturating_sub(matched_position);
            for offset in 0..=(end - start) {
                rows.push(PreviewRow {
                    line_number: start_number + offset,
                    text: self.source.combined_lines[start + offset].clone(),
                    is_center: offset == matched_position,
                    is_separator: false,
                    block_index,
                });
            }
            rows.push(PreviewRow {
                line_number: 0,
                text: String::new(),
                is_center: false,
                is_separator: true,
                block_index,
            });
        }
        self.preview_rows = rows;
    }

    pub fn matched_row_indices(&self) -> Vec<usize> {
        self.preview_rows
            .iter()
            .enumerate()
            .filter(|(_, row)| row.is_center)
            .map(|(index, _)| index)
            .collect()
    }
}

pub struct SearchRequest {
    pub project_root: PathBuf,
    pub project_root_text: String,
    pub query: String,
    pub mode: SearchMode,
}

struct PreparedMatcher {
    query: String,
    lower_query: String,
    mode: SearchMode,
    regex: Option<Regex>,
}

impl PreparedMatcher {
    fn new(query: &str, mode: SearchMode) -> PreparedMatcher {
        let regex = match mode {
            SearchMode::MatchWholeWord => RegexBuilder::new(query)
                .case_insensitive(true)
                .build()
                .ok(),
            SearchMode::MatchCaseWholeWord => {
                RegexBuilder::new(query).build().ok()
            }
            SearchMode::Regex => RegexBuilder::new(query).build().ok(),
            _ => None,
        };
        PreparedMatcher {
            query: query.to_string(),
            lower_query: query.to_lowercase(),
            mode,
            regex,
        }
    }

    fn count(&self, text: &str) -> usize {
        if self.query.is_empty() {
            return 0;
        }
        match self.mode {
            SearchMode::Simple => {
                text.to_lowercase().matches(&self.lower_query).count()
            }
            SearchMode::MatchCase => text.matches(&self.query).count(),
            SearchMode::MatchWholeWord
            | SearchMode::MatchCaseWholeWord
            | SearchMode::Regex => {
                let Some(regex) = &self.regex else {
                    return 0;
                };
                if matches!(self.mode, SearchMode::Regex) {
                    regex.find_iter(text).count()
                } else {
                    regex
                        .find_iter(text)
                        .filter(|matched| {
                            let before_ok = if matched.start() == 0 {
                                true
                            } else {
                                let previous = text[..matched.start()]
                                    .chars()
                                    .next_back()
                                    .unwrap();
                                !is_word_char(previous)
                            };
                            let after_ok = if matched.end() >= text.len() {
                                true
                            } else {
                                let next = text[matched.end()..]
                                    .chars()
                                    .next()
                                    .unwrap();
                                !is_word_char(next)
                            };
                            before_ok && after_ok
                        })
                        .count()
                }
            }
        }
    }
}

fn is_word_char(ch: char) -> bool {
    ch == '_' || ch.is_alphanumeric()
}

pub fn execute_search(request: &SearchRequest) -> Vec<FileResult> {
    if request.query.is_empty() {
        return Vec::new();
    }
    let mut command = Command::new("rg");
    match request.mode {
        SearchMode::Simple => {
            command.arg("--ignore-case").arg("--fixed-strings");
        }
        SearchMode::MatchCase => {
            command.arg("--fixed-strings");
        }
        SearchMode::MatchWholeWord => {
            command.arg("--ignore-case").arg("--word-regexp");
        }
        SearchMode::MatchCaseWholeWord => {
            command.arg("--word-regexp");
        }
        SearchMode::Regex => {}
    }
    command
        .arg("--line-number")
        .arg("--with-filename")
        .arg(&request.query)
        .arg(&request.project_root)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null());

    let output = match command.output() {
        Ok(output) => output,
        Err(_) => return Vec::new(),
    };

    let matcher = PreparedMatcher::new(&request.query, request.mode);
    let mut results: Vec<FileResult> = Vec::new();
    let mut index_by_path: HashMap<String, usize> = HashMap::new();

    for line in output_lines(&output.stdout) {
        let mut parts = line.splitn(3, ':');
        let Some(path) = parts.next() else { continue };
        let Some(line_number_text) = parts.next() else {
            continue;
        };
        let Some(content) = parts.next() else { continue };
        let Ok(line_number) = line_number_text.parse::<usize>() else {
            continue;
        };
        let file_index = if let Some(index) = index_by_path.get(path) {
            *index
        } else {
            let display = display_path(path, &request.project_root_text);
            let result = FileResult {
                id: NEXT_FILE_ID.fetch_add(1, Ordering::Relaxed),
                actual_path: path.to_string(),
                display_path: display,
                count: 0,
                matches: Vec::new(),
                source: PreviewSource::default(),
                preview_rows: Vec::new(),
            };
            results.push(result);
            let index = results.len() - 1;
            index_by_path.insert(path.to_string(), index);
            index
        };
        let file = &mut results[file_index];
        if file
            .matches
            .iter()
            .any(|entry| entry.line_number == line_number)
        {
            continue;
        }
        file.count += matcher.count(content);
        file.matches.push(MatchEntry {
            line_number,
            text: content.to_string(),
            valid_index: 0,
        });
    }

    // Build preview data, file by file.  The line buffers are kept
    // cumulatively while later files are processed, following the
    // behaviour of the original program: the context of the first
    // match of a file may include lines from the preceding file.
    let mut combined_lines: Vec<String> = Vec::new();
    let mut previous_external_match: Option<usize> = None;
    for file in results.iter_mut() {
        let (valid_lines, index_by_line_number) =
            read_valid_lines(&file.actual_path);
        let base = combined_lines.len();
        let own_count = valid_lines.len();
        for matched in file.matches.iter_mut() {
            if let Some(valid_index) = index_by_line_number.get(&matched.line_number) {
                matched.valid_index = *valid_index;
            } else {
                matched.valid_index = matched.line_number.saturating_sub(1);
            }
        }
        combined_lines.extend(valid_lines.iter().cloned());
        file.source = PreviewSource {
            combined_lines: combined_lines.clone(),
            base_index: base,
            own_count,
            prev_external_match_idx: previous_external_match,
        };
        file.rebuild_preview();
        if let Some(last) = file.matches.last() {
            previous_external_match = Some(base + last.valid_index);
        }
    }

    let _ = highlight_regex;
    results
}

fn display_path(path: &str, project_root_text: &str) -> String {
    let prefix = format!("{}/", project_root_text);
    path.strip_prefix(&prefix)
        .unwrap_or(path)
        .to_string()
}

fn output_lines(bytes: &[u8]) -> Vec<String> {
    let mut lines = Vec::new();
    let mut start = 0usize;
    let mut index = 0usize;
    while index < bytes.len() {
        if bytes[index] == b'\n' {
            let mut segment = &bytes[start..index];
            if segment.ends_with(b"\r") {
                segment = &segment[..segment.len() - 1];
            }
            if let Ok(text) = std::str::from_utf8(segment) {
                lines.push(text.to_string());
            }
            start = index + 1;
        }
        index += 1;
    }
    if start < bytes.len() {
        let segment = &bytes[start..];
        if let Ok(text) = std::str::from_utf8(segment) {
            lines.push(text.to_string());
        }
    }
    lines
}

fn read_valid_lines(path: &str) -> (Vec<String>, HashMap<usize, usize>) {
    let Ok(bytes) = std::fs::read(path) else {
        return (Vec::new(), HashMap::new());
    };
    let mut valid: Vec<String> = Vec::new();
    let mut by_line_number: HashMap<usize, usize> = HashMap::new();
    let mut seen: HashSet<usize> = HashSet::new();
    let mut physical = 1usize;
    let mut start = 0usize;
    let mut index = 0usize;
    let _ = &mut seen;
    while index < bytes.len() {
        if bytes[index] == b'\n' {
            let mut segment = &bytes[start..index];
            if segment.ends_with(b"\r") {
                segment = &segment[..segment.len() - 1];
            }
            if let Ok(text) = std::str::from_utf8(segment) {
                by_line_number.insert(physical, valid.len());
                valid.push(text.to_string());
            }
            physical += 1;
            start = index + 1;
        }
        index += 1;
    }
    if start < bytes.len() {
        let segment = &bytes[start..];
        if let Ok(text) = std::str::from_utf8(segment) {
            by_line_number.insert(physical, valid.len());
            valid.push(text.to_string());
        }
    }
    (valid, by_line_number)
}
EOF
