            let mut segment = &bytes[start..index];
            if segment.ends_with(b"\r") {
                segment = &segment[..segment.len() - 1];
            }
            if let Ok(text) = std::str::from_utf8(segment) {
                lines.push(text.to_string());
            }
            start = index + 1;
        }
        index += 1;
    }
    if start < bytes.len() {
