pub fn replacement_regex(query: &str, mode: SearchMode) -> Option<Regex> {
    let (pattern, case_insensitive) = match mode {
        SearchMode::Simple => (regex::escape(query), true),
        SearchMode::MatchCase => (regex::escape(query), false),
        SearchMode::MatchWholeWord => {
            (format!(r"\b{}\b", regex::escape(query)), true)
        }
        SearchMode::MatchCaseWholeWord => {
            (format!(r"\b{}\b", regex::escape(query)), false)
        }
        // Deliberately treated like a case-insensitive literal search.
        SearchMode::Regex => (regex::escape(query), true),
    };
    RegexBuilder::new(&pattern)
        .case_insensitive(case_insensitive)
        .build()
        .ok()
}

pub fn highlight_regex(query: &str, mode: SearchMode) -> Option<Regex> {
    let (pattern, case_insensitive) = match mode {
        SearchMode::Simple => (regex::escape(query), true),
        SearchMode::MatchCase => (regex::escape(query), false),
        SearchMode::MatchWholeWord => (format!(r"\b{}\b", query), true),
        SearchMode::MatchCaseWholeWord => {
            (format!(r"\b{}\b", query), false)
        }
        SearchMode::Regex => (query.to_string(), false),
    };
    RegexBuilder::new(&pattern)
        .case_insensitive(case_insensitive)
        .build()
        .ok()
}

pub fn highlight_ranges(
    text: &str,
    query: &str,
    mode: SearchMode,
) -> Vec<(usize, usize)> {
    if query.is_empty() {
        return Vec::new();
    }
    let Some(regex) = highlight_regex(query, mode) else {
        return Vec::new();
    };
    regex
        .find_iter(text)
        .map(|matched| (matched.start(), matched.end()))
        .collect()
}

pub fn preserve_case(matched: &str, replacement: &str) -> String {
    let is_upper = matched.to_uppercase() == matched
        && matched.to_lowercase() != matched;
    if is_upper {
        replacement.to_uppercase()
    } else if matched
        .chars()
        .next()
        .map(|ch| ch.is_uppercase())
        .unwrap_or(false)
    {
        let mut chars = replacement.chars();
        match chars.next() {
            Some(first) => {
                let upper: String = first.to_uppercase().collect();
                format!("{}{}", upper, chars.as_str().to_lowercase())
            }
            None => String::new(),
        }
    } else {
        replacement.to_lowercase()
    }
}

pub fn transform_text(
    content: &str,
    query: &str,
    replacement: &str,
    search_mode: SearchMode,
    replace_mode: ReplaceMode,
) -> String {
    if replace_mode == ReplaceMode::DeleteLine {
        return content.to_string();
    }
    let Some(regex) = replacement_regex(query, search_mode) else {
        return content.to_string();
    };
    match replace_mode {
        ReplaceMode::PreserveCase => regex
            .replace_all(content, |captures: &regex::Captures<'_>| {
                let matched = captures.get(0).map(|m| m.as_str()).unwrap_or("");
                preserve_case(matched, replacement)
            })
            .into_owned(),
        _ => regex
            .replace_all(content, NoExpand(replacement))
            .into_owned(),
    }
}

