    std::fs::read_to_string(path).expect("Unable to read file")
}

pub fn write_file(path: &str, content: &str) {
    std::fs::write(path, content).expect("Unable to write file")
}

pub fn replace_file(
    file: &FileResult,
    query: &str,
    replacement: &str,
    search_mode: SearchMode,
    replace_mode: ReplaceMode,
) {
    if replace_mode == ReplaceMode::DeleteLine {
        delete_lines_in_file(file);
        return;
    }
    let content = read_file(&file.actual_path);
    let transformed = transform_text(
        &content,
        query,
        replacement,
        search_mode,
        replace_mode,
    );
    write_file(&file.actual_path, &transformed);
}

pub fn delete_lines_in_file(file: &FileResult) {
    let content = read_file(&file.actual_path);
    let matched_lines: HashSet<usize> = file
        .matches
        .iter()
        .map(|entry| entry.line_number)
        .collect();
    let retained: Vec<&str> = content
        .lines()
        .enumerate()
        .filter(|(index, _)| !matched_lines.contains(&(index + 1)))
        .map(|(_, line)| line)
        .collect();
    write_file(&file.actual_path, &retained.join("\n"));
}

pub fn replace_line(
    file: &FileResult,
    line_number: usize,
    query: &str,
    replacement: &str,
    search_mode: SearchMode,
    replace_mode: ReplaceMode,
) {
    let content = read_file(&file.actual_path);
    let mut lines: Vec<String> =
        content.lines().map(|line| line.to_string()).collect();
    let index = line_number - 1;
    if replace_mode == ReplaceMode::DeleteLine {
        lines.remove(index);
    } else {
        lines[index] = transform_text(
            &lines[index].clone(),
            query,
            replacement,
            search_mode,
            replace_mode,
        );
    }
    write_file(&file.actual_path, &lines.join("\n"));
}
