use crate::config::{Action, Config};
use crate::input::Input;
use crate::replace;
use crate::search::{
    execute_search, FileResult, ReplaceMode, SearchMode, SearchRequest,
};
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Alignment, Constraint, Direction, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, BorderType, Borders, Clear, Paragraph, Wrap};
use ratatui::Frame;
use std::path::PathBuf;
use std::sync::mpsc::{self, Receiver, Sender};
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Focus {
    Search,
    Replace,
    Result,
    Preview,
    ConfirmHidden,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HelpReturn {
    Main(Focus),
    ConfirmHidden,
}

#[derive(Clone, Debug)]
struct Notification {
    message: String,
    expires: Instant,
}

pub struct App {
    project_root: PathBuf,
    project_root_text: String,
    config: Config,
    focus: Focus,
    search_input: Input,
    replace_input: Input,
    search_mode: SearchMode,
    replace_mode: ReplaceMode,
    results: Vec<FileResult>,
    result_selected: Option<usize>,
    result_offset: usize,
    preview_selected_row: Option<usize>,
    preview_offset: usize,
    preview_match_ordinal: Option<usize>,
    preview_target_file_id: Option<usize>,
    confirm_open: bool,
    confirm_continue_selected: bool,
    confirm_return_focus: Focus,
    help_open: bool,
    help_tab: usize,
    help_return: HelpReturn,
    notifications: Vec<Notification>,
    search_sender: Sender<SearchRequest>,
    search_receiver: Receiver<Vec<FileResult>>,
    pub should_quit: bool,
    pub should_suspend: bool,
}

impl App {
    pub fn new(project_root: PathBuf, config: Config) -> App {
        let (request_sender, request_receiver) =
            mpsc::channel::<SearchRequest>();
        let (result_sender, result_receiver) =
            mpsc::channel::<Vec<FileResult>>();
        std::thread::spawn(move || {
            while let Ok(request) = request_receiver.recv() {
                let results = execute_search(&request);
                if result_sender.send(results).is_err() {
                    break;
                }
            }
        });
        let project_root_text = project_root.to_string_lossy().into_owned();
        App {
            project_root,
            project_root_text,
            config,
            focus: Focus::Search,
            search_input: Input::new(),
            replace_input: Input::new(),
            search_mode: SearchMode::Simple,
            replace_mode: ReplaceMode::Simple,
            results: Vec::new(),
            result_selected: None,
            result_offset: 0,
            preview_selected_row: None,
            preview_offset: 0,
            preview_match_ordinal: None,
            preview_target_file_id: None,
            confirm_open: false,
            confirm_continue_selected: false,
            confirm_return_focus: Focus::Search,
            help_open: false,
            help_tab: 0,
            help_return: HelpReturn::Main(Focus::Search),
            notifications: Vec::new(),
            search_sender: request_sender,
            search_receiver: result_receiver,
            should_quit: false,
            should_suspend: false,
        }
    }

    pub fn apply_pending_search_results(&mut self) {
        while let Ok(results) = self.search_receiver.try_recv() {
            self.results = results;
            if self.results.is_empty() {
                self.result_selected = None;
            } else if let Some(selected) = self.result_selected {
                if selected >= self.results.len() {
                    self.result_selected = Some(self.results.len() - 1);
                }
            }
        }
    }

    pub fn prune_notifications(&mut self) {
        let now = Instant::now();
        self.notifications.retain(|note| note.expires > now);
    }

    pub fn poll_timeout(&self) -> Duration {
        Duration::from_millis(400)
    }

    fn schedule_search(&self) {
        if self.search_input.is_empty() {
            return;
        }
        let request = SearchRequest {
            project_root: self.project_root.clone(),
            project_root_text: self.project_root_text.clone(),
            query: self.search_input.value.clone(),
            mode: self.search_mode,
        };
        let _ = self.search_sender.send(request);
    }

    fn push_notification(&mut self, message: &str) {
        self.notifications.push(Notification {
            message: message.to_string(),
            expires: Instant::now() + Duration::from_millis(3000),
        });
    }

    // -- Actions -------------------------------------------------------

    fn cycle_focus(&mut self, forward: bool) {
        let current = if self.focus == Focus::ConfirmHidden {
            self.confirm_return_focus
        } else {
            self.focus
        };
        if current == Focus::Preview {
            // Preview does not take part in the loop over the three
            // main panes; looping from it stays where it is.
            self.focus = Focus::Preview;
            return;
        }
        let order = [Focus::Search, Focus::Replace, Focus::Result];
        let index = order.iter().position(|item| *item == current).unwrap_or(0);
        let next = if forward {
            (index + 1) % order.len()
        } else {
            (index + order.len() - 1) % order.len()
        };
        self.focus = order[next];
    }

    fn open_confirm(&mut self) -> bool {
        if self.search_input.is_empty() {
            return false;
        }
        if self.focus != Focus::ConfirmHidden {
            self.confirm_return_focus = self.focus;
        }
        self.confirm_open = true;
        true
    }

    fn open_help(&mut self) {
        if self.help_open {
            return;
        }
        self.help_return = if self.confirm_open {
            self.confirm_open = false;
            HelpReturn::ConfirmHidden
        } else if self.focus == Focus::ConfirmHidden {
            HelpReturn::ConfirmHidden
        } else {
            HelpReturn::Main(self.focus)
        };
        self.help_open = true;
    }

    fn close_help(&mut self) {
        self.help_open = false;
        match self.help_return {
            HelpReturn::Main(focus) => self.focus = focus,
            HelpReturn::ConfirmHidden => self.focus = Focus::ConfirmHidden,
        }
    }

    fn handle_action(&mut self, action: Action) {
        match action {
            Action::Quit => self.should_quit = true,
            Action::Suspend => self.should_suspend = true,
            Action::Refresh => {
                if self.focus == Focus::Search {
                    self.schedule_search();
                }
            }
            Action::LoopOverTabs => self.cycle_focus(true),
            Action::BackLoopOverTabs => self.cycle_focus(false),
            Action::ProcessReplace => {
                self.open_confirm();
            }
            Action::ShowHelp => self.open_help(),
            Action::Resume | Action::Help | Action::Tick | Action::Render => {}
        }
    }

    // -- Top level key dispatch ----------------------------------------

    pub fn handle_key(&mut self, event: KeyEvent) {
        if self.help_open {
            self.handle_help_key(event);
            return;
        }
        if self.confirm_open {
            self.handle_confirm_key(event);
            return;
        }
        if self.focus == Focus::ConfirmHidden {
            if let Some(action) = self.config.action_for(event) {
                match action {
                    Action::LoopOverTabs => self.cycle_focus(true),
                    Action::BackLoopOverTabs => self.cycle_focus(false),
                    Action::Quit
                    | Action::Suspend
                    | Action::ShowHelp
                    | Action::ProcessReplace => self.handle_action(action),
                    _ => {}
                }
            }
            return;
        }

        if let Some(action) = self.config.action_for(event) {
            if action == Action::Refresh
                && matches!(self.focus, Focus::Result | Focus::Preview)
            {
                // In the list panes Ctrl-r behaves like the plain
                // replace key rather than as a global refresh.
                if self.focus == Focus::Result {
                    self.replace_selected_file();
                } else {
                    self.replace_selected_line();
                }
                return;
            }
            self.handle_action(action);
            return;
        }

        if event.code == KeyCode::Char('n')
            && event.modifiers.contains(KeyModifiers::CONTROL)
        {
            match self.focus {
                Focus::Search => {
                    self.search_mode = self.search_mode.next();
                    self.schedule_search();
                }
                Focus::Replace => {
                    self.replace_mode = self.replace_mode.next();
                    self.schedule_search();
                }
                _ => {}
            }
            return;
        }

        match self.focus {
            Focus::Search => self.handle_input(event, true),
            Focus::Replace => {
                if self.replace_mode != ReplaceMode::DeleteLine {
                    self.handle_input(event, false);
                }
            }
            Focus::Result => self.handle_result_key(event),
            Focus::Preview => self.handle_preview_key(event),
            Focus::ConfirmHidden => {}
        }
    }

    fn handle_help_key(&mut self, event: KeyEvent) {
        if let Some(action) = self.config.action_for(event) {
            match action {
                Action::Quit | Action::Suspend => {
                    self.handle_action(action);
                    return;
                }
                Action::ShowHelp => return,
                Action::ProcessReplace => {
                    // ProcessReplace closes the help dialog and opens
                    // the confirm dialog, but only if a dialog can
                    // actually be opened (non-empty search text).
                    if !self.search_input.is_empty() {
                        let origin = self.help_return;
                        self.help_open = false;
                        match origin {
                            HelpReturn::Main(focus) => {
                                self.confirm_return_focus = focus;
                            }
                            HelpReturn::ConfirmHidden => {}
                        }
                        self.confirm_open = true;
                    }
                    return;
                }
                _ => {}
            }
        }
        match event.code {
            KeyCode::Esc => self.close_help(),
            KeyCode::Char('q') => self.close_help(),
            KeyCode::Right => {
                self.help_tab = (self.help_tab + 1) % 2;
            }
            KeyCode::Left => {
                self.help_tab = (self.help_tab + 1) % 2;
            }
            KeyCode::Tab => {
                self.help_tab = (self.help_tab + 1) % 2;
            }
            _ => {}
        }
    }

    fn handle_confirm_key(&mut self, event: KeyEvent) {
        if let Some(action) = self.config.action_for(event) {
            match action {
                Action::Quit | Action::Suspend => {
                    self.handle_action(action);
                    return;
                }
                Action::ShowHelp => {
                    self.open_help();
                    return;
                }
                _ => {}
            }
        }
        if event.code == KeyCode::Char('n')
            && event.modifiers.contains(KeyModifiers::CONTROL)
        {
            // Ctrl-n dismisses the confirm dialog without replacing.
            self.confirm_open = false;
            self.focus = Focus::ConfirmHidden;
            return;
        }
        match event.code {
            KeyCode::Esc => {
                self.confirm_open = false;
                self.focus = Focus::ConfirmHidden;
            }
            KeyCode::Enter => {
                if self.confirm_continue_selected {
                    self.process_replace_all();
                } else {
                    self.confirm_open = false;
                    self.focus = Focus::ConfirmHidden;
                }
            }
            KeyCode::Tab
            | KeyCode::BackTab
            | KeyCode::Left
            | KeyCode::Right
            | KeyCode::Up
            | KeyCode::Down
            | KeyCode::Char('h')
            | KeyCode::Char('l')
            | KeyCode::Char('j')
            | KeyCode::Char('k') => {
                self.confirm_continue_selected = !self.confirm_continue_selected;
            }
            _ => {}
        }
    }

    // -- Inputs ---------------------------------------------------------

    fn handle_input(&mut self, event: KeyEvent, is_search: bool) {
        let mut changed = false;
        let mut search_again = false;
        if event.modifiers.contains(KeyModifiers::CONTROL) {
            match event.code {
                KeyCode::Char('a') => {
                    if is_search {
                        self.search_input.move_start()
                    } else {
                        self.replace_input.move_start()
                    }
                }
                KeyCode::Char('e') => {
                    if is_search {
                        self.search_input.move_end()
                    } else {
                        self.replace_input.move_end()
                    }
                }
                KeyCode::Char('w') => {
                    changed = if is_search {
                        self.search_input.delete_to_previous_word()
                    } else {
                        self.replace_input.delete_to_previous_word()
                    };
                }
                KeyCode::Char('u') => {
                    changed = if is_search {
                        self.search_input.delete_all()
                    } else {
                        self.replace_input.delete_all()
                    };
                }
                KeyCode::Char('k') => {
                    changed = if is_search {
                        self.search_input.delete_to_end()
                    } else {
                        self.replace_input.delete_to_end()
                    };
                }
                KeyCode::Char('h') => {
                    changed = if is_search {
                        self.search_input.delete_previous_char()
                    } else {
                        self.replace_input.delete_previous_char()
                    };
                }
                KeyCode::Left => {
                    if is_search {
                        self.search_input.move_previous_word()
                    } else {
                        self.replace_input.move_previous_word()
                    }
                }
                KeyCode::Right => {
                    if is_search {
                        self.search_input.move_next_word()
                    } else {
                        self.replace_input.move_next_word()
                    }
                }
                KeyCode::Delete => {
                    changed = if is_search {
                        self.search_input.delete_to_next_word()
                    } else {
                        self.replace_input.delete_to_next_word()
                    };
                }
                _ => {}
            }
        } else if event.modifiers.contains(KeyModifiers::ALT) {
            if event.code == KeyCode::Backspace {
                changed = if is_search {
                    self.search_input.delete_to_previous_word()
                } else {
                    self.replace_input.delete_to_previous_word()
                };
            }
        } else {
            match event.code {
                KeyCode::Enter => {
                    if is_search {
                        search_again = true;
                    }
                }
                KeyCode::Char(ch) => {
                    changed = if is_search {
                        self.search_input.insert_char(ch)
                    } else {
                        self.replace_input.insert_char(ch)
                    };
                }
                KeyCode::Backspace => {
                    changed = if is_search {
                        self.search_input.delete_previous_char()
                    } else {
                        self.replace_input.delete_previous_char()
                    };
                }
                KeyCode::Delete => {
                    changed = if is_search {
                        self.search_input.delete_next_char()
                    } else {
                        self.replace_input.delete_next_char()
                    };
                }
                KeyCode::Left => {
                    if is_search {
                        self.search_input.move_left()
                    } else {
                        self.replace_input.move_left()
                    }
                }
                KeyCode::Right => {
                    if is_search {
                        self.search_input.move_right()
                    } else {
                        self.replace_input.move_right()
                    }
                }
                KeyCode::Home => {
                    if is_search {
                        self.search_input.move_start()
                    } else {
                        self.replace_input.move_start()
                    }
                }
                KeyCode::End => {
                    if is_search {
                        self.search_input.move_end()
                    } else {
                        self.replace_input.move_end()
                    }
                }
                _ => {}
            }
        }
        if is_search && (changed || search_again) {
            self.schedule_search();
        }
    }

    // -- Result list ----------------------------------------------------

    fn reset_preview_selection(&mut self) {
        self.preview_selected_row = None;
        self.preview_match_ordinal = None;
        self.preview_offset = 0;
    }

    fn set_result_selected(&mut self, selected: Option<usize>) {
        if selected != self.result_selected {
            self.result_selected = selected;
            self.reset_preview_selection();
        }
    }

    fn next_result(&mut self) {
        if self.results.is_empty() {
            return;
        }
        let next = match self.result_selected {
            None => 0,
            Some(index) => (index + 1) % self.results.len(),
        };
        self.set_result_selected(Some(next));
    }

    fn previous_result(&mut self) {
        if self.results.is_empty() {
            return;
        }
        let previous = match self.result_selected {
            None => self.results.len() - 1,
            Some(index) => {
                (index + self.results.len() - 1) % self.results.len()
            }
        };
        self.set_result_selected(Some(previous));
    }

    fn handle_result_key(&mut self, event: KeyEvent) {
        match event.code {
            KeyCode::Enter => {
                self.preview_target_file_id = self
                    .result_selected
                    .and_then(|index| self.results.get(index))
                    .map(|file| file.id);
                self.focus = Focus::Preview;
            }
            KeyCode::Char('j') | KeyCode::Down => self.next_result(),
            KeyCode::Char('k') | KeyCode::Up => self.previous_result(),
            KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                if !self.results.is_empty() {
                    self.set_result_selected(Some(0));
                }
            }
            KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                if !self.results.is_empty() {
                    self.set_result_selected(Some(self.results.len() - 1));
                }
            }
            KeyCode::Char('r') => self.replace_selected_file(),
            KeyCode::Char('d') => self.delete_selected_file(),
            _ => {}
        }
    }

    fn remove_result_at(&mut self, index: usize) {
        if index >= self.results.len() {
            return;
        }
        self.results.remove(index);
        if self.results.is_empty() {
            self.result_selected = None;
            self.reset_preview_selection();
        } else if let Some(selected) = self.result_selected {
            if selected > index {
                self.result_selected = Some(selected - 1);
                // The file under the cursor changes identity here only
                // when the removed file was before it; in practice the
                // callers remove the selected file itself, whose new
                // occupant is a different file.
                self.reset_preview_selection();
            } else if selected == index {
                if selected >= self.results.len() {
                    self.result_selected = Some(self.results.len() - 1);
                }
                self.reset_preview_selection();
            }
        }
    }

    fn replace_selected_file(&mut self) {
        let Some(index) = self.result_selected else {
            return;
        };
        let Some(file) = self.results.get(index).cloned() else {
            return;
        };
        replace::replace_file(
            &file,
            &self.search_input.value.clone(),
            &self.replace_input.value.clone(),
            self.search_mode,
            self.replace_mode,
        );
        self.push_notification("File replacement completed successfully");
        self.remove_result_at(index);
    }

    fn delete_selected_file(&mut self) {
        let Some(index) = self.result_selected else {
            return;
        };
        if index < self.results.len() {
            self.remove_result_at(index);
        }
    }

    // -- Preview --------------------------------------------------------

    fn current_preview_file(&self) -> Option<&FileResult> {
        self.result_selected
            .and_then(|index| self.results.get(index))
    }

    fn next_preview_match(&mut self) {
        let Some(file) = self.current_preview_file() else {
            return;
        };
        let rows = file.matched_row_indices();
        if rows.is_empty() {
            return;
        }
        let ordinal = match self.preview_match_ordinal {
            None => 0,
            Some(current) if current >= rows.len() => 0,
            Some(current) => (current + 1) % rows.len(),
        };
        self.preview_match_ordinal = Some(ordinal);
        self.preview_selected_row = rows.get(ordinal).copied();
    }

    fn previous_preview_match(&mut self) {
        let Some(file) = self.current_preview_file() else {
            return;
        };
        let rows = file.matched_row_indices();
        if rows.is_empty() {
            return;
        }
        let ordinal = match self.preview_match_ordinal {
            None => rows.len() - 1,
            Some(current) if current >= rows.len() => rows.len() - 1,
            Some(current) => (current + rows.len() - 1) % rows.len(),
        };
        self.preview_match_ordinal = Some(ordinal);
        self.preview_selected_row = rows.get(ordinal).copied();
    }

    fn handle_preview_key(&mut self, event: KeyEvent) {
        match event.code {
            KeyCode::Enter | KeyCode::Esc => {
                self.focus = Focus::Result;
            }
            KeyCode::Char('j') | KeyCode::Down => self.next_preview_match(),
            KeyCode::Char('k') | KeyCode::Up => self.previous_preview_match(),
            KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                if let Some(file) = self.current_preview_file() {
                    let rows = file.matched_row_indices();
                    if !rows.is_empty() {
                        self.preview_match_ordinal = Some(0);
                        self.preview_selected_row = rows.first().copied();
                    }
                }
            }
            KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                if let Some(file) = self.current_preview_file() {
                    let rows = file.matched_row_indices();
                    if !rows.is_empty() {
                        self.preview_match_ordinal = Some(rows.len() - 1);
                        self.preview_selected_row = rows.last().copied();
                    }
                }
            }
            KeyCode::Char('r') => self.replace_selected_line(),
            KeyCode::Char('d') => self.delete_selected_line(),
            _ => {}
        }
    }

    fn preview_target_index(&self) -> Option<usize> {
        let target = self.preview_target_file_id?;
        self.results.iter().position(|file| file.id == target)
    }

    fn replace_selected_line(&mut self) {
        let Some(ordinal) = self.preview_match_ordinal else {
            return;
        };
        let Some(index) = self.preview_target_index() else {
            return;
        };
        let Some(file) = self.results.get(index).cloned() else {
            return;
        };
        let Some(entry) = file.matches.get(ordinal).cloned() else {
            return;
        };
        replace::replace_line(
            &file,
            entry.line_number,
            &self.search_input.value.clone(),
            &self.replace_input.value.clone(),
            self.search_mode,
            self.replace_mode,
        );
        self.push_notification("Line replacement completed successfully");
        self.remove_preview_match(index, ordinal);
    }

    fn delete_selected_line(&mut self) {
        let Some(ordinal) = self.preview_match_ordinal else {
            return;
        };
        let Some(index) = self.preview_target_index() else {
            return;
        };
        if self
            .results
            .get(index)
            .map(|file| ordinal >= file.matches.len())
            .unwrap_or(true)
        {
            return;
        }
        self.remove_preview_match(index, ordinal);
    }

    fn remove_preview_match(&mut self, index: usize, ordinal: usize) {
        let file_now_empty = {
            let Some(file) = self.results.get_mut(index) else {
                return;
            };
            if ordinal >= file.matches.len() {
                return;
            }
            file.count = file.count.saturating_sub(1);
            file.matches.remove(ordinal);
            if file.matches.is_empty() {
                true
            } else {
                file.rebuild_preview();
                false
            }
        };
        if file_now_empty {
            self.results.remove(index);
            if self.results.is_empty() {
                self.result_selected = None;
            } else if let Some(selected) = self.result_selected {
                if selected >= self.results.len() {
                    self.result_selected = Some(self.results.len() - 1);
                }
            }
            self.preview_match_ordinal = None;
        }
    }

    // -- Replace all ------------------------------------------------------

    fn process_replace_all(&mut self) {
        let files = self.results.clone();
        let query = self.search_input.value.clone();
        let replacement = self.replace_input.value.clone();
        for file in &files {
            replace::replace_file(
                file,
                &query,
                &replacement,
                self.search_mode,
                self.replace_mode,
            );
        }
        self.confirm_open = false;
        self.results.clear();
        self.result_selected = None;
        self.reset_preview_selection();
        self.result_offset = 0;
        self.focus = Focus::Search;
        self.push_notification("Search and replace completed successfully");
    }

    // -- Drawing ----------------------------------------------------------

    fn effective_focus(&self) -> Option<Focus> {
        if self.help_open || self.confirm_open {
            None
        } else if self.focus == Focus::ConfirmHidden {
            None
        } else {
            Some(self.focus)
        }
    }

    pub fn draw(&mut self, frame: &mut Frame) {
        let area = frame.area();
        let vertical = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Min(0), Constraint::Length(1)])
            .split(area);
        let main = vertical[0];
        let footer_area = vertical[1];

        let horizontal = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Percentage(30), Constraint::Percentage(70)])
            .split(main);
        let left = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(3),
                Constraint::Length(3),
                Constraint::Min(0),
            ])
            .split(horizontal[0]);

        let effective_focus = self.effective_focus();

        self.draw_search_input(frame, left[0], effective_focus);
        self.draw_replace_input(frame, left[1], effective_focus);
        self.draw_results(frame, left[2], effective_focus);
        self.draw_preview(frame, horizontal[1], effective_focus);
        self.draw_footer(frame, footer_area);
        self.draw_notifications(frame, main);
        if self.confirm_open {
            self.draw_confirm(frame, area);
        }
        if self.help_open {
            self.draw_help(frame, area);
        }
    }

    fn input_block(
        &self,
        title: &'static str,
        mode: &'static str,
        focused: bool,
        dark: bool,
    ) -> Block<'static> {
        let border_style = if focused {
            Style::default()
                .fg(Color::Green)
                .add_modifier(Modifier::BOLD)
        } else if dark {
            Style::default().fg(Color::DarkGray)
        } else {
            Style::default().fg(Color::White)
        };
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(border_style)
            .title(Line::from(format!("[{}]", mode)).right_aligned())
            .title(Line::from(title))
    }

    fn draw_search_input(
        &mut self,
        frame: &mut Frame,
        area: Rect,
        effective_focus: Option<Focus>,
    ) {
        let focused = effective_focus == Some(Focus::Search);
        let block = self.input_block(
            "Search",
            self.search_mode.title(),
            focused,
            false,
        );
        let inner_width = block.inner(area).width;
        let scroll = self.search_input.visual_scroll(inner_width as usize);
        let widget = Paragraph::new(self.search_input.value.clone())
            .block(block)
            .scroll((0, scroll as u16));
        frame.render_widget(widget, area);
        if focused {
            let inner = Rect {
                x: area.x + 1,
                y: area.y + 1,
                width: area.width.saturating_sub(2),
                height: area.height.saturating_sub(2),
            };
            let cursor_x = inner.x.saturating_add(
                (self.search_input.visual_cursor() - scroll) as u16,
            );
            if inner.width > 0 && inner.height > 0 {
                frame.set_cursor_position((cursor_x, inner.y));
            }
        }
    }

    fn draw_replace_input(
        &mut self,
        frame: &mut Frame,
        area: Rect,
        effective_focus: Option<Focus>,
    ) {
        let focused = effective_focus == Some(Focus::Replace);
        let is_delete = self.replace_mode == ReplaceMode::DeleteLine;
        let block = self.input_block(
            "Replace",
            self.replace_mode.title(),
            focused,
            is_delete,
        );
        if is_delete {
            let widget = Paragraph::new("[Entire line will be deleted]")
                .style(Style::default().fg(Color::DarkGray))
                .block(block);
            frame.render_widget(widget, area);
            return;
        }
        let inner_width = block.inner(area).width;
        let scroll = self.replace_input.visual_scroll(inner_width as usize);
        let widget = Paragraph::new(self.replace_input.value.clone())
            .block(block)
            .scroll((0, scroll as u16));
        frame.render_widget(widget, area);
        if focused {
            let inner = Rect {
                x: area.x + 1,
                y: area.y + 1,
                width: area.width.saturating_sub(2),
                height: area.height.saturating_sub(2),
            };
            let cursor_x = inner.x.saturating_add(
                (self.replace_input.visual_cursor() - scroll) as u16,
            );
            if inner.width > 0 && inner.height > 0 {
                frame.set_cursor_position((cursor_x, inner.y));
            }
        }
    }

    fn draw_results(
        &mut self,
        frame: &mut Frame,
        area: Rect,
        effective_focus: Option<Focus>,
    ) {
        let focused = effective_focus == Some(Focus::Result);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(if focused {
                Style::default()
                    .fg(Color::Green)
                    .add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(Color::White)
            })
            .title("Result List");
        let inner_height = block.inner(area).height as usize;
        // Normalise and scroll the selection into view.
        if let Some(selected) = self.result_selected {
            if self.results.is_empty() {
                self.result_selected = None;
                self.result_offset = 0;
            } else {
                let selected = selected.min(self.results.len() - 1);
                self.result_selected = Some(selected);
                self.result_offset = adjusted_offset(
                    selected,
                    self.result_offset,
                    inner_height,
                );
            }
        } else {
            self.result_offset = 0;
        }

        let lines: Vec<Line> = self
            .results
            .iter()
            .enumerate()
            .map(|(index, file)| {
                let mut line = Line::from(vec![
                    Span::styled(
                        file.display_path.clone(),
                        Style::default().fg(Color::White),
                    ),
                    Span::styled(" (", Style::default().fg(Color::White)),
                    Span::styled(
                        file.count.to_string(),
                        Style::default().fg(Color::Yellow),
                    ),
                    Span::styled(")", Style::default().fg(Color::White)),
                ]);
                if self.result_selected == Some(index) {
                    line = line.style(Style::default().bg(Color::Blue));
                }
                line
            })
            .collect();
        let widget = Paragraph::new(lines)
            .block(block)
            .scroll((self.result_offset as u16, 0));
        frame.render_widget(widget, area);
    }

    fn draw_preview(
        &mut self,
        frame: &mut Frame,
        area: Rect,
        effective_focus: Option<Focus>,
    ) {
        let focused = effective_focus == Some(Focus::Preview);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(if focused {
                Style::default().fg(Color::Green)
            } else {
                Style::default()
            })
            .title("Preview");
        let inner = block.inner(area);
        let inner_height = inner.height as usize;
        let inner_width = inner.width as usize;

        let Some(file) = self.current_preview_file().cloned() else {
            frame.render_widget(Paragraph::new("").block(block), area);
            self.preview_offset = 0;
            return;
        };

        if let Some(selected) = self.preview_selected_row {
            if selected < file.preview_rows.len() {
                self.preview_offset = adjusted_offset(
                    selected,
                    self.preview_offset,
                    inner_height,
                );
            }
        } else {
            self.preview_offset = 0;
        }

        let selected_row = self.preview_selected_row;
        let selected_block = selected_row
            .and_then(|row| file.preview_rows.get(row))
            .map(|row| row.block_index)
            .or_else(|| self.preview_match_ordinal);
        let has_selection = selected_row.is_some()
            && selected_row.unwrap_or(usize::MAX) < file.preview_rows.len();

        let mut lines: Vec<Line> = Vec::new();
        for (row_index, row) in file.preview_rows.iter().enumerate() {
            let is_selected_row = has_selection && selected_row == Some(row_index);
            if row.is_separator {
                let dash_count = if has_selection {
                    inner_width.saturating_sub(2)
                } else {
                    inner_width
                };
                let color = if has_selection
                    && selected_block
                        .map(|selected| row.block_index <= selected)
                        .unwrap_or(false)
                {
                    Color::Yellow
                } else {
                    Color::DarkGray
                };
                let mut spans: Vec<Span> = Vec::new();
                if has_selection {
                    spans.push(Span::raw("  "));
                }
                spans.push(Span::styled(
                    "-".repeat(dash_count),
                    Style::default().fg(color),
                ));
                let mut line = Line::from(spans);
                if is_selected_row {
                    line = line.style(
                        Style::default()
                            .fg(Color::White)
                            .add_modifier(Modifier::BOLD),
                    );
                }
                lines.push(line);
                continue;
            }

            let mut spans: Vec<Span> = Vec::new();
            if has_selection {
                spans.push(Span::raw(if is_selected_row { "> " } else { "  " }));
            }
            let number_style = if row.is_center {
                Style::default().fg(Color::LightGreen)
            } else {
                Style::default().fg(Color::Blue)
            };
            spans.push(Span::styled(
                format!("{:4} ", row.line_number),
                number_style,
            ));
            if row.is_center {
                spans.extend(self.center_line_spans(&row.text));
            } else {
                spans.push(Span::styled(
                    row.text.clone(),
                    Style::default().fg(Color::DarkGray),
                ));
            }
            if is_selected_row {
                spans = spans
                    .into_iter()
                    .map(|span| {
                        let style = span
                            .style
                            .patch(
                                Style::default()
                                    .fg(Color::White)
                                    .add_modifier(Modifier::BOLD),
                            );
                        Span::styled(span.content, style)
                    })
                    .collect();
            }
            lines.push(Line::from(spans));
        }

        let widget = Paragraph::new(lines)
            .block(block)
            .scroll((self.preview_offset as u16, 0));
        frame.render_widget(widget, area);
    }

    fn center_line_spans(&self, text: &str) -> Vec<Span<'static>> {
        if self.replace_mode == ReplaceMode::DeleteLine {
            return vec![Span::styled(
                text.to_string(),
                Style::default()
                    .fg(Color::White)
                    .bg(Color::Red)
                    .add_modifier(Modifier::CROSSED_OUT),
            )];
        }
        let ranges = replace::highlight_ranges(
            text,
            &self.search_input.value,
            self.search_mode,
        );
        if ranges.is_empty() {
            return vec![Span::raw(text.to_string())];
        }
        let replace_empty = self.replace_input.is_empty();
        let mut spans: Vec<Span> = Vec::new();
        let mut last = 0usize;
        for (start, end) in ranges {
            let start = start.min(text.len());
            let end = end.min(text.len());
            if start > last {
                spans.push(Span::raw(text[last..start].to_string()));
            }
            let matched = &text[start..end];
            if replace_empty {
                spans.push(Span::styled(
                    matched.to_string(),
                    Style::default().bg(Color::Blue),
                ));
            } else {
                spans.push(Span::styled(
                    matched.to_string(),
                    Style::default()
                        .fg(Color::White)
                        .bg(Color::LightRed)
                        .add_modifier(Modifier::CROSSED_OUT),
                ));
                let replacement_text =
                    if self.replace_mode == ReplaceMode::PreserveCase {
                        replace::preserve_case(
                            matched,
                            &self.replace_input.value,
                        )
                    } else {
                        self.replace_input.value.clone()
                    };
                spans.push(Span::styled(
                    replacement_text,
                    Style::default()
                        .fg(Color::White)
                        .bg(Color::Green),
                ));
            }
            last = end;
        }
        if last < text.len() {
            spans.push(Span::raw(text[last..].to_string()));
        }
        if spans.is_empty() {
            spans.push(Span::raw(String::new()));
        }
        spans
    }

    fn draw_footer(&self, frame: &mut Frame, area: Rect) {
        let text = if self.help_open {
            "Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>"
        } else if self.confirm_open || self.focus == Focus::ConfirmHidden {
            "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left: <h>, Right: <l>, Loop: <Tab>"
        } else {
            match self.focus {
                Focus::Search => {
                    "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>"
                }
                Focus::Replace => {
                    "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>"
                }
                Focus::Result => {
                    "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>"
                }
                Focus::Preview => {
                    "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete line: <d>"
                }
                Focus::ConfirmHidden => {
                    "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left: <h>, Right: <l>, Loop: <Tab>"
                }
            }
        };
        let widget = Paragraph::new(text)
            .style(Style::default().fg(Color::Blue));
        frame.render_widget(widget, area);
    }

    fn draw_notifications(&self, frame: &mut Frame, area: Rect) {
        // Notifications stack upwards from the bottom-right corner of
        // the main area; the oldest message sits at the bottom.
        for (index, note) in self.notifications.iter().enumerate() {
            let text_width = note.message.chars().count();
            let width = (text_width + 4) as u16;
            let width = width.min(area.width);
            if width == 0 || area.height < 3 {
                continue;
            }
            let height = 3u16.min(area.height);
            let offset_from_bottom = (index as u16) * 3;
            if offset_from_bottom >= area.height {
                break;
            }
            let x = area.x + area.width.saturating_sub(width + 1);
            let bottom = area.y + area.height.saturating_sub(1);
            let y = bottom.saturating_sub(height - 1 + offset_from_bottom);
            let note_area = Rect {
                x,
                y,
                width,
                height,
            };
            let block = Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(
                    Style::default()
                        .fg(Color::Blue)
                        .add_modifier(Modifier::BOLD),
                )
                .title("Notification");
            let widget = Paragraph::new(note.message.clone())
                .style(Style::default().fg(Color::Blue))
                .block(block);
            frame.render_widget(Clear, note_area);
            frame.render_widget(widget, note_area);
        }
    }

    fn draw_confirm(&self, frame: &mut Frame, area: Rect) {
        let message = if self.replace_input.is_empty() {
            "Replace text is empty, and replacing with an empty string will remove the matched text."
        } else {
            "This action will modify the files in this directory."
        };
        let needed = (message.chars().count() + 4) as u16;
        let width = needed.min(area.width);
        let height = 8u16.min(area.height);
        if width == 0 || height == 0 {
            return;
        }
        let dialog = Rect {
            x: area.x + area.width.saturating_sub(width) / 2,
            y: area.y + area.height.saturating_sub(height) / 2,
            width,
            height,
        };
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(Style::default().fg(Color::Yellow))
            .title(Line::from("Confirm Dialog").centered());
        let inner = block.inner(dialog);
        frame.render_widget(Clear, dialog);
        frame.render_widget(block, dialog);

        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Length(3), Constraint::Min(0)])
            .split(inner);
        let message_widget = Paragraph::new(vec![
            Line::from(""),
            Line::from(message),
            Line::from("Are you sure you want to continue?"),
        ])
        .alignment(Alignment::Center)
        .wrap(Wrap { trim: true })
        .style(Style::default().fg(Color::White));
        frame.render_widget(message_widget, chunks[0]);

        let continue_style = if self.confirm_continue_selected {
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::White)
        };
        let cancel_style = if self.confirm_continue_selected {
            Style::default().fg(Color::White)
        } else {
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD)
        };
        let buttons = Paragraph::new(vec![
            Line::from(""),
            Line::from(""),
            Line::from(vec![
