    fn draw_help(&self, frame: &mut Frame, area: Rect) {
        let width = 80u16.min(area.width);
        let height = 15u16.min(area.height);
        if width == 0 || height == 0 {
            return;
        }
        let dialog = Rect {
            x: area.x + area.width.saturating_sub(width) / 2,
            y: area.y + area.height.saturating_sub(height) / 2,
            width,
            height,
        };
        let tab1_style = if self.help_tab == 0 {
            Style::default().fg(Color::Green)
        } else {
            Style::default()
        };
        let tab2_style = if self.help_tab == 1 {
            Style::default().fg(Color::Green)
        } else {
            Style::default()
        };
        let left_title = Line::from(vec![
            Span::styled(" [1] Global ", tab1_style),
            Span::raw("─"),
            Span::styled(" [2] Navigation ", tab2_style),
        ]);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(Style::default().fg(Color::Yellow))
            .title(Line::from("Press 'q' to close").right_aligned())
            .title(left_title);
        frame.render_widget(Clear, dialog);

        let items: Vec<&str> = if self.help_tab == 0 {
            vec![
                " - Ctrl-c: Quit",
                " - Ctrl-d: Quit",
                " - Ctrl-b: Help dialog",
                " - Ctrl-o: Process Replace For All Files",
                " - Ctrl-n: Loop through search and replace modes",
                " - Enter: Select/Deselect file",
                " - d: delete file/delete line from the replace process",
                " - r: Replace Selected File Or Line",
            ]
        } else {
            vec![
                " - Tab: Loop through panes",
                " - j/UpArrow: Move up",
                " - k/DownArrow: Move down",
                " - h/g/LeftArrow: Move to Top",
                " - l/G/RightArrow: Move to Bottom",
            ]
        };
        let mut lines: Vec<Line> = vec![Line::from("")];
        for item in items {
            lines.push(Line::from(Span::styled(
                item.to_string(),
                Style::default().fg(Color::White),
            )));
        }
        let widget = Paragraph::new(lines)
            .block(block)
            .wrap(Wrap { trim: true });
        frame.render_widget(widget, dialog);
    }
}

fn adjusted_offset(selected: usize, offset: usize, height: usize) -> usize {
    if height == 0 {
        return 0;
    }
    if selected < offset {
        selected
    } else if selected >= offset + height {
        selected + 1 - height
    } else {
        offset
    }
}
