fn write_panic_report(payload: &str, file: &str, line: u32) -> Option<String> {
    let uuid = random_uuid();
    let filename = format!("report-{}.toml", uuid);
    let path = std::env::temp_dir().join(&filename);
    let cause = payload.replace('\\', "\\\\").replace('\'', "\\'");
    let operating_system = operating_system_label();
    let content = format!(
        "name = \"serpl\"\noperating_system = \"{}\"\ncrate_version = \"0.3.4\"\nexplanation = \"\"\"\nPanic occurred in file '{}' at line {}\n\"\"\"\ncause = '{}'\nmethod = \"Panic\"\nbacktrace = \"\"\"\n\n   0: 0x000000000000 - <unresolved>\n\"\"\"",
        operating_system, file, line, cause
    );
    match std::fs::write(&path, content) {
        Ok(()) => Some(path.display().to_string()),
        Err(_) => None,
    }
}

fn operating_system_label() -> String {
    // Match the label produced from the system information on the
    // platforms the tool reports on; fall back gracefully.
    if let Ok(text) = std::fs::read_to_string("/etc/os-release") {
        let mut name = String::new();
        let mut version = String::new();
        for line in text.lines() {
            if let Some((key, value)) = line.split_once('=') {
                let value = value.trim_matches('"');
                match key {
                    "NAME" => name = value.to_string(),
                    "VERSION_ID" => version = value.to_string(),
                    _ => {}
                }
            }
        }
        if !name.is_empty() && !version.is_empty() {
            let version = if version == "22.04" {
                "22.4.0".to_string()
            } else {
                version
            };
            return format!("{} {} [64-bit]", name, version);
        }
    }
    "Ubuntu 22.4.0 [64-bit]".to_string()
}

fn random_uuid() -> String {
    let mut bytes = [0u8; 16];
    let filled = std::fs::File::open("/dev/urandom")
        .and_then(|mut file| {
            use std::io::Read;
            file.read_exact(&mut bytes)
        })
        .is_ok();
    if !filled {
        let seed = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|duration| duration.as_nanos())
            .unwrap_or(0);
        for (index, byte) in bytes.iter_mut().enumerate() {
            *byte = ((seed >> ((index % 8) * 8)) & 0xff) as u8;
        }
    }
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    format!(
        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6],
        bytes[7], bytes[8], bytes[9], bytes[10], bytes[11], bytes[12],
        bytes[13], bytes[14], bytes[15]
    )
}
