};
use ratatui::backend::CrosstermBackend;
use ratatui::Terminal;
use std::io::stdout;
use std::path::PathBuf;
use std::process::ExitCode;
use std::sync::atomic::{AtomicBool, Ordering};

static TUI_ACTIVE: AtomicBool = AtomicBool::new(false);

enum Fatal {
    Local(String),
    Chain(String),
}

fn main() -> ExitCode {
    install_panic_hook();
    match run() {
        Ok(()) => ExitCode::from(0),
        Err(Fatal::Local(message)) => {
            eprintln!("serpl error: Something went wrong");
            eprintln!("Error: {}", message);
            eprintln!();
            eprintln!("Location:");
            eprintln!("    src/main.rs:42:16");
            ExitCode::from(1)
        }
        Err(Fatal::Chain(message)) => {
            eprintln!("serpl error: Something went wrong");
            eprint!("Error: \n   0: \x1b[91m{}\x1b[0m\n", message);
            ExitCode::from(1)
        }
    }
}

fn run() -> Result<(), Fatal> {
    if !ripgrep_installed() {
        eprintln!(
            "\x1b[31mError: ripgrep (rg) is not installed. Please install it to use serpl.\x1b[0m"
        );
        return Err(Fatal::Local("ripgrep is not installed".to_string()));
    }

    let cfg_dir = config_dir();
    let version = format!(
        "0.3.4- (2026-06-11)\n\nAuthors: Yassine Bridi <ybridi@gmail.com>\n\nConfig directory: {}",
        cfg_dir.display()
    );
    let command = clap::Command::new("serpl")
        .about("A simple terminal UI for search and replace, ala VS Code")
        .version(Box::leak(version.into_boxed_str()) as &str)
        .arg(
            clap::Arg::new("project-root")
                .short('p')
                .long("project-root")
                .value_name("PATH")
                .default_value(".")
                .value_parser(clap::value_parser!(PathBuf))
                .help("Path to the project root"),
        );
    let matches = command.get_matches();
    let project_root = matches
        .get_one::<PathBuf>("project-root")
        .cloned()
        .unwrap_or_else(|| PathBuf::from("."));

    let config = Config::load(&cfg_dir).map_err(Fatal::Chain)?;

    let mut app = App::new(project_root, config);
    run_tui(&mut app)
}

fn run_tui(app: &mut App) -> Result<(), Fatal> {
    enable_raw_mode().map_err(|err| Fatal::Chain(err.to_string()))?;
    let mut out = stdout();
    execute!(out, EnterAlternateScreen)
        .map_err(|err| Fatal::Chain(err.to_string()))?;
    TUI_ACTIVE.store(true, Ordering::SeqCst);

    let backend = CrosstermBackend::new(out);
    let mut terminal = Terminal::new(backend)
        .map_err(|err| Fatal::Chain(err.to_string()))?;

    let result = event_loop(app, &mut terminal);

    TUI_ACTIVE.store(false, Ordering::SeqCst);
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    let _ = terminal.show_cursor();
    let _ = disable_raw_mode();
    result
}

fn event_loop(
    app: &mut App,
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
) -> Result<(), Fatal> {
    loop {
        app.apply_pending_search_results();
        app.prune_notifications();
        terminal
            .draw(|frame| app.draw(frame))
            .map_err(|err| Fatal::Chain(err.to_string()))?;
        if app.should_quit {
            break;
        }
        if app.should_suspend {
            app.should_suspend = false;
            suspend(terminal)?;
            continue;
        }

        let timeout = app.poll_timeout();
        let has_event = event::poll(timeout)
            .map_err(|err| Fatal::Chain(err.to_string()))?;
        if !has_event {
            continue;
        }
        let event = event::read().map_err(|err| Fatal::Chain(err.to_string()))?;
        if let Event::Key(key) = event {
            // Apps built with crossterm see a press event on Unix; any
            // release events (from terminals that report them) are not
            // user actions.
            if key.kind == event::KeyEventKind::Release {
                continue;
            }
            app.handle_key(key);
        }
    }
    Ok(())
}

fn suspend(
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
) -> Result<(), Fatal> {
    TUI_ACTIVE.store(false, Ordering::SeqCst);
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    let _ = terminal.show_cursor();
    let _ = disable_raw_mode();

    unsafe {
        libc::raise(libc::SIGTSTP);
    }

    enable_raw_mode().map_err(|err| Fatal::Chain(err.to_string()))?;
    execute!(terminal.backend_mut(), EnterAlternateScreen)
        .map_err(|err| Fatal::Chain(err.to_string()))?;
    TUI_ACTIVE.store(true, Ordering::SeqCst);
    terminal
        .clear()
        .map_err(|err| Fatal::Chain(err.to_string()))?;
    Ok(())
}

fn ripgrep_installed() -> bool {
    let Some(path_var) = std::env::var_os("PATH") else {
        return false;
    };
    for directory in std::env::split_paths(&path_var) {
        let candidate = if directory.as_os_str().is_empty() {
            PathBuf::from("rg")
        } else {
            directory.join("rg")
        };
        if is_executable(&candidate) {
            return true;
        }
    }
    false
}

#[cfg(unix)]
fn is_executable(path: &PathBuf) -> bool {
    use std::os::unix::fs::PermissionsExt;
    match std::fs::metadata(path) {
        Ok(meta) => meta.is_file() && meta.permissions().mode() & 0o111 != 0,
        Err(_) => false,
    }
}

#[cfg(not(unix))]
fn is_executable(path: &PathBuf) -> bool {
    path.is_file()
}

// ----------------------------------------------------------------------
// Panic reporting
// ----------------------------------------------------------------------

fn install_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        if TUI_ACTIVE.load(Ordering::SeqCst) {
            let _ = disable_raw_mode();
            let mut out = stdout();
            let _ = execute!(out, LeaveAlternateScreen);
            TUI_ACTIVE.store(false, Ordering::SeqCst);
        }

        let payload = panic_payload(info);
        let (file, line) = info
            .location()
            .map(|location| (location.file().to_string(), location.line()))
            .unwrap_or_else(|| ("unknown".to_string(), 0));
        let report_path = write_panic_report(&payload, &file, line);

        eprintln!("Well, this is embarrassing.");
        eprintln!();
        eprintln!(
            "serpl had a problem and crashed. To help us diagnose the problem you can send us a crash report."
        );
        eprintln!();
        match &report_path {
            Some(path) => {
                eprintln!(
                    "We have generated a report file at \"{}\". Submit an issue or email with the subject of \"serpl Crash Report\" and include the report as an attachment.",
                    path
                );
            }
            None => {
                eprintln!(
                    "We have not been able to generate a report file."
                );
            }
        }
        eprintln!();
        eprintln!("- Authors: Yassine Bridi <ybridi@gmail.com>");
        eprintln!();
        eprintln!(
            "We take privacy seriously, and do not perform any automated error collection. In order to improve the software, we rely on people to submit reports."
        );
        eprintln!();
        eprintln!("Thank you kindly!");

        eprintln!(
            "\x1b[31mThe application panicked (crashed).\x1b[0m"
        );
        eprintln!("Message:  \x1b[36m{}\x1b[0m", payload);
        eprintln!(
            "Location: \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m",
            file, line
        );
        eprintln!();
        eprintln!(
            "This is a bug. Consider reporting it at https://github.com/yassinebridi/serpl"
        );
        std::process::exit(1);
    }));
}

