        if la==lb:
            print(f"[{label}] TEXT OK ({len(la)} lines)")
        else:
            ok=False
            print(f"[{label}] TEXT DIFF")
            for i in range(max(len(la),len(lb))):
                xa=la[i] if i<len(la) else "<missing>"
                xb=lb[i] if i<len(lb) else "<missing>"
                if xa!=xb:
