            diffs=[i for i in range(max(len(ea),len(eb))) if (ea[i] if i<len(ea) else "")!=(eb[i] if i<len(eb) else "")]
            print(f"[{label}] ESC DIFF lines {diffs[:10]}")
            for i in diffs[:6]:
                print(f"  E{i} orig: {ea[i]!r}")
                print(f"  E{i} ours: {eb[i]!r}")
    return ok
