import subprocess, time, os, shutil, sys
BIN_ORIG="/workspace/executable"
BIN_OURS="/tmp/ours"

def tmux(*args):
    subprocess.run(["tmux"]+list(args), stderr=subprocess.DEVNULL)
def start(binpath, cmd_dir, w=100, h=30):
    subprocess.run(["tmux","kill-session","-t","test"], stderr=subprocess.DEVNULL)
    subprocess.run(["tmux","new-session","-d","-s","test","-x",str(w),"-y",str(h)], check=True)
    tmux("send-keys","-t","test", f"cd {cmd_dir} && {binpath}", "Enter")
    # wait ui
    for _ in range(50):
        time.sleep(0.05)
        try:
            if any("Search" in l for l in cap()):
                return
        except Exception: pass
def cap():
    return subprocess.check_output(["tmux","capture-pane","-t","test","-p"]).decode().splitlines()
def cap_e():
    return subprocess.check_output(["tmux","capture-pane","-t","test","-p","-e"]).decode().splitlines()
def send(*keys, delay=0.25):
    if keys: subprocess.run(["tmux","send-keys","-t","test"]+list(keys), stderr=subprocess.DEVNULL)
    time.sleep(delay)
def typetext(txt, delay=0.25):
    subprocess.run(["tmux","set-buffer","--",txt], check=True)
    subprocess.run(["tmux","paste-buffer","-t","test"], check=True)
    time.sleep(delay)
def run(binpath, steps, cmd_dir="/tmp/proj3", w=100, h=30):
    start(binpath, cmd_dir, w, h)
    snaps={}
    for step in steps:
        kind=step[0]
        if kind=="type": typetext(step[1], step[2] if len(step)>2 else 0.3)
        elif kind=="key": send(step[1], delay=step[2] if len(step)>2 else 0.25)
        elif kind=="keys": send(*step[1], delay=step[2] if len(step)>2 else 0.25)
        elif kind=="wait": time.sleep(step[1])
        elif kind=="snap": snaps[step[1]] = (cap(), cap_e())
        elif kind=="setup": pass
    subprocess.run(["tmux","kill-session","-t","test"], stderr=subprocess.DEVNULL)
    return snaps

def compare(name, steps, cmd_dir="/tmp/proj3", w=100, h=30, setup=None):
    if setup: setup()
    a=run(BIN_ORIG, steps, cmd_dir, w, h)
    if setup: setup()
    b=run(BIN_OURS, steps, cmd_dir, w, h)
    print(f"\n##### {name} #####")
    ok=True
    for label in a:
        la,ea=a[label]; lb,eb=b[label]
        if la==lb:
            print(f"[{label}] TEXT OK ({len(la)} lines)")
        else:
            ok=False
            print(f"[{label}] TEXT DIFF")
            for i in range(max(len(la),len(lb))):
                xa=la[i] if i<len(la) else "<missing>"
                xb=lb[i] if i<len(lb) else "<missing>"
                if xa!=xb:
                    print(f"  L{i} orig: {xa!r}")
                    print(f"  L{i} ours: {xb!r}")
        if ea==eb:
            print(f"[{label}] ESC OK")
        else:
            # summarize differing lines
            diffs=[i for i in range(max(len(ea),len(eb))) if (ea[i] if i<len(ea) else "")!=(eb[i] if i<len(eb) else "")]
            print(f"[{label}] ESC DIFF lines {diffs[:10]}")
            for i in diffs[:6]:
                print(f"  E{i} orig: {ea[i]!r}")
                print(f"  E{i} ours: {eb[i]!r}")
    return ok
