import subprocess, time, sys
sys.path.insert(0,'/tmp')
import difftest

def run(binpath, actions):
    subprocess.run(["tmux","kill-session","-t","test"], stderr=subprocess.DEVNULL)
    subprocess.run(["tmux","new-session","-d","-s","test","-x","80","-y","20"], check=True)
    subprocess.run(["tmux","send-keys","-t","test", f"cd /tmp/projmany2 && {binpath}", "Enter"]); time.sleep(0.7)
    difftest.typetext("hello"); time.sleep(1.0)
    difftest.send("Tab","Tab")
    metrics=[]
    def metric(label):
        ls=difftest.cap(); e=difftest.cap_e(); selpos=None
        for i in range(7,18):
            if i<len(e) and "48;5;4" in e[i]:
                # make sure it's result segment (left 30 chars) - escape segment before second border is hard; approximate based on selected plain row having bg at start - use text and e segment split
                selpos=i-7
        metrics.append((label, selpos))
    metric("initial")
    for a in actions:
        if isinstance(a, list):
            for k in a: difftest.send(k, delay=0.1)
        else: difftest.send(a)
        metric(a if isinstance(a,str) else "+".join(a))
    subprocess.run(["tmux","kill-session","-t","test"], stderr=subprocess.DEVNULL)
    return metrics
actions=["j","j","j","j","j","j","j","j","j","j","j","j","j","G","k","k","k","k","k","g","j","j"]
for binpath in [difftest.BIN_ORIG, difftest.BIN_OURS]:
    print(binpath, run(binpath, actions))
