        let Some(path) = data
            .get("path")
            .and_then(|path| path.get("text"))
            .and_then(|text| text.as_str())
        else {
            continue;
        };
        let Some(raw_content) = data
            .get("lines")
            .and_then(|lines| lines.get("text"))
            .and_then(|text| text.as_str())
        else {
            continue;
        };
        let Some(line_number) = data
            .get("line_number")
            .and_then(|number| number.as_u64())
        else {
            continue;
        };
        let line_number = line_number as usize;
        let mut content = raw_content;
        if content.ends_with('\\n') {
            content = &content[..content.len() - 1];
            if content.ends_with('\\r') {
                content = &content[..content.len() - 1];
            }
        }
        let submatch_count = data
            .get("submatches")
            .and_then(|matches| matches.as_array())
            .map(|matches| matches.len())
            .unwrap_or(0);

        let file_index = if let Some(index) = index_by_path.get(path) {
            *index
        } else {
            let display = display_path(path, &request.project_root_text);
            let result = FileResult {
                id: NEXT_FILE_ID.fetch_add(1, Ordering::Relaxed),
                highlight_query: request.query.clone(),
                highlight_mode: request.mode,
                actual_path: path.to_string(),
                display_path: display,
                count: 0,
                matches: Vec::new(),
                source: PreviewSource::default(),
                preview_rows: Vec::new(),
            };
            results.push(result);
            let index = results.len() - 1;
            index_by_path.insert(path.to_string(), index);
            index
        };
        let file = &mut results[file_index];
        if file
            .matches
            .iter()
            .any(|entry| entry.line_number == line_number)
        {
            continue;
        }
        file.count += submatch_count;
        file.matches.push(MatchEntry {
            line_number,
            text: content.to_string(),
            valid_index: 0,
        });
    }

