p='src/main.rs'
s=open(p).read()
s=s.replace('''        if let Ok(width) = columns.trim().parse::<usize>() {
            if width > 0 {
                return width;
            }
        }''','''        if let Ok(width) = columns.parse::<usize>() {
            return width;
        }''')
open(p,'w').write(s)
PY
cargo build --release --offline 2>&1 | tail -2; cp target/release/serpl /tmp/ours; COLUMNS=0 /tmp/ours --help 2>&1 | head -10; echo exit:$?; COLUMNS=" 40 " /tmp/ours --help | head -8

